extern "C" int Phoenix_CreatureDrawAudit_ShouldLog(int creatureType)
{
  static const bool kPhoenixCreatureDrawAuditEnabled = false;
  return kPhoenixCreatureDrawAuditEnabled && creatureType == 2221;
}

extern "C" void Phoenix_CreatureDrawAudit_Log(const char* format, ...)
{
  static const bool kPhoenixCreatureDrawAuditEnabled = false;
  if (!kPhoenixCreatureDrawAuditEnabled)
    return;

  static char logPath[MAX_PATH] = {0};
  static DWORD startTime = 0;
  static bool initialized = false;

  if (!initialized)
  {
    initialized = true;
    if (GetModuleFileNameA(NULL, logPath, MAX_PATH) > 0)
    {
      char* lastSlash = strrchr(logPath, '\\');
      if (lastSlash)
      {
        strcpy(lastSlash + 1, "data");
        CreateDirectoryA(logPath, NULL);
        strcat(logPath, "\\log");
        CreateDirectoryA(logPath, NULL);
        strcat(logPath, "\\creature_draw_audit.log");
      }
      else
      {
        strcpy(logPath, "data\\log\\creature_draw_audit.log");
      }
    }
    else
    {
      strcpy(logPath, "data\\log\\creature_draw_audit.log");
    }

    FILE* fp = _fsopen(logPath, "w", _SH_DENYNO);
    if (fp)
    {
      fprintf(fp, "Phoenix creature draw audit start. target creatureType=2221\n");
      fclose(fp);
    }
  }

  FILE* fp = _fsopen(logPath, "a", _SH_DENYNO);
  if (!fp)
    return;

  if (startTime == 0)
    startTime = GetTickCount();

  char buf[2048];
  va_list args;
  va_start(args, format);
  _vsnprintf(buf, sizeof(buf), format, args);
  va_end(args);
  buf[sizeof(buf) - 1] = 0;

  fprintf(fp, "[%u][TID:%u] %s\n",
          GetTickCount() - startTime, GetCurrentThreadId(), buf);
  fflush(fp);
  fclose(fp);
}

