bool Phoenix_ItemOutputPerf_FileExists(const char* path)
{
  FILE* fp = fopen(path, "rb");
  if (!fp)
    return false;
  fclose(fp);
  return true;
}

bool Phoenix_ItemOutputPerf_IsEnabled()
{
  DWORD now = GetTickCount();
  if (g_PhoenixItemOutputLastProbeCheckMs == 0 ||
      now - g_PhoenixItemOutputLastProbeCheckMs >= 1000)
  {
    g_PhoenixItemOutputProbeEnabled = Phoenix_NoLogPerf_IsEnabled();
    g_PhoenixItemOutputLastProbeCheckMs = now;
  }
  return g_PhoenixItemOutputProbeEnabled;
}

