DWORD Phoenix_CreatureWarmup_MakeResourceKey(const MTopView::ITEM_DRAW_SPRITE_RESOURCE_KEY& key)
{
  return ((DWORD)(key.pack & 0x0F) << 28) ^
         ((DWORD)(key.body & 0x0FFF) << 16) ^
         (DWORD)(key.spriteID & 0xFFFF);
}

