void Phoenix_CreatureWarmup_EnsureSummaryBegin()
{
  PhoenixCreatureWarmupSummary& summary = g_PhoenixCreatureWarmupSummary;
  if (summary.queueSizeBegin == 0 &&
      summary.enqueueCount == 0 &&
      summary.dedupeSkipCount == 0 &&
      summary.processedCount == 0 &&
      summary.cacheHit == 0 &&
      summary.cacheMiss == 0)
  {
    summary.queueSizeBegin = (unsigned int)g_PhoenixCreatureWarmupQueue.size();
    summary.queueSizeEnd = summary.queueSizeBegin;
  }
}

void Phoenix_CreatureWarmup_RecordQueueEnd()
{
  g_PhoenixCreatureWarmupSummary.queueSizeEnd =
      (unsigned int)g_PhoenixCreatureWarmupQueue.size();
}

void Phoenix_CreatureWarmup_RecordDedupeSkip()
{
  Phoenix_CreatureWarmup_EnsureSummaryBegin();
  g_PhoenixCreatureWarmupSummary.dedupeSkipCount++;
  Phoenix_CreatureWarmup_RecordQueueEnd();
}

void Phoenix_CreatureWarmup_RecordEnqueue()
{
  Phoenix_CreatureWarmup_EnsureSummaryBegin();
  g_PhoenixCreatureWarmupSummary.enqueueCount++;
  Phoenix_CreatureWarmup_RecordQueueEnd();
}

void Phoenix_CreatureWarmup_RecordCacheHitAtEnqueue()
{
  Phoenix_CreatureWarmup_EnsureSummaryBegin();
  g_PhoenixCreatureWarmupSummary.cacheHit++;
  Phoenix_CreatureWarmup_RecordQueueEnd();
}

void Phoenix_CreatureWarmup_RecordProcessed(const PhoenixCreatureWarmupRequest& request,
                                            int cacheHit,
                                            double ms,
                                            int stage)
{
  Phoenix_CreatureWarmup_EnsureSummaryBegin();
  PhoenixCreatureWarmupSummary& summary = g_PhoenixCreatureWarmupSummary;
  summary.processedCount++;
  summary.totalMs += ms;
  if (cacheHit)
  {
    summary.cacheHit++;
    summary.readyCount++;
    summary.cacheLookupMs += ms;
  }
  else
  {
    summary.cacheMiss++;
    if (stage == 4)
      summary.blockingLazyLoadMs += ms;
    else
      summary.unknownMs += ms;
  }

  if (request.key.spriteID >= 0)
    g_PhoenixCreatureWarmupUniqueResources.insert(request.resourceKey);

  if (ms > summary.maxMs)
  {
    summary.maxMs = ms;
    summary.maxTick = GetTickCount();
    summary.maxObjectID = request.objectID;
    summary.maxClass = request.objectClass;
    summary.maxType = request.objectType;
    summary.maxAction = request.action;
    summary.maxDirection = request.direction;
    summary.maxFrame = request.key.frame;
    summary.maxSpriteKey = request.key.spriteID;
    summary.maxResourceKey = (int)request.resourceKey;
    summary.maxReason = request.reason;
    summary.maxStage = stage;
  }

  if (ms > 5.0)
  {
    summary.singleResourceBlockingLoadCount++;
    if (ms > summary.maxSingleResourceBlockingMs)
      summary.maxSingleResourceBlockingMs = ms;
  }

  Phoenix_CreatureWarmup_RecordQueueEnd();
}

void Phoenix_CreatureWarmup_WriteCsv()
{
  const PhoenixCreatureWarmupSummary& summary = g_PhoenixCreatureWarmupSummary;
  if (summary.enqueueCount == 0 &&
      summary.dedupeSkipCount == 0 &&
      summary.processedCount == 0 &&
      summary.renderDeferredLazyLoadCount == 0 &&
      summary.blockingLazyLoadCount == 0 &&
      summary.cacheHit == 0 &&
      summary.cacheMiss == 0)
    return;

  const bool fileAlreadyExists =
      Phoenix_ItemOutputPerf_FileExists("resource_streaming_summary_fix.csv");
  FILE* fp = fopen("resource_streaming_summary_fix.csv", "a");
  if (!fp)
    return;

  if (!fileAlreadyExists)
  {
    fprintf(fp,
            "tick,queue_size_begin,queue_size_end,enqueue_count,dedupe_skip_count,"
            "processed_count,ready_count,failed_count,cache_hit,cache_miss,"
            "cpu_decode_count,render_upload_count,total_ms,cpu_decode_ms,render_upload_ms,"
            "file_io_ms,spk_parse_ms,decode_ms,surface_create_ms,surface_copy_ms,"
            "texture_create_ms,allocation_ms,unknown_ms,budget_ms,budget_exceeded,"
            "max_single_resource_ms,max_single_resource_key,max_single_object_kind,"
            "max_single_object_id,max_single_class,max_single_type,max_single_action,"
            "max_single_direction,max_single_frame,max_single_stage,"
            "render_deferred_lazy_load_count,blocking_lazy_load_count,blocking_lazy_load_ms\n");
  }

  fprintf(fp,
          "%lu,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.4f,%.4f,%.4f,"
          "%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%d,"
          "%.4f,%d,%s,%lu,%d,%d,%d,%d,%d,%s,%u,%u,%.4f\n",
          GetTickCount(),
          summary.queueSizeBegin,
          summary.queueSizeEnd,
          summary.enqueueCount,
          summary.dedupeSkipCount,
          summary.processedCount,
          summary.readyCount,
          summary.failedCount,
          summary.cacheHit,
          summary.cacheMiss,
          summary.cpuDecodeCount,
          summary.renderUploadCount,
          summary.totalMs,
          summary.cpuDecodeMs,
          summary.renderUploadMs,
          summary.fileIoMs,
          0.0,
          summary.decodeMs,
          summary.surfaceCreateMs,
          summary.surfaceCopyMs,
          0.0,
          summary.allocationMs,
          summary.unknownMs,
          summary.budgetMs,
          summary.budgetExceeded,
          summary.maxMs,
          summary.maxResourceKey,
          Phoenix_CreatureWarmup_GetReasonName(summary.maxReason),
          (unsigned long)summary.maxObjectID,
          summary.maxClass,
          summary.maxType,
          summary.maxAction,
          summary.maxDirection,
          summary.maxFrame,
          Phoenix_CreatureWarmup_GetStageName(summary.maxStage),
          summary.renderDeferredLazyLoadCount,
          summary.blockingLazyLoadCount,
          summary.blockingLazyLoadMs);

  fclose(fp);

  const bool queueFileExists =
      Phoenix_ItemOutputPerf_FileExists("resource_streaming_queue_summary_fix.csv");
  FILE* qfp = fopen("resource_streaming_queue_summary_fix.csv", "a");
  if (!qfp)
    return;

  if (!queueFileExists)
  {
    fprintf(qfp,
            "tick,queue_size_begin,queue_size_end,queued_resource_count,"
            "seen_resource_count,unique_ready_resource_count,enqueue_count,dedupe_skip_count,"
            "cache_hit,cache_miss,render_deferred_lazy_load_count,state\n");
  }

  fprintf(qfp,
          "%lu,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%s\n",
          GetTickCount(),
          summary.queueSizeBegin,
          summary.queueSizeEnd,
          (unsigned int)g_PhoenixCreatureWarmupQueue.size(),
          (unsigned int)g_PhoenixCreatureWarmupSeenResources.size(),
          (unsigned int)g_PhoenixCreatureWarmupUniqueResources.size(),
          summary.enqueueCount,
          summary.dedupeSkipCount,
          summary.cacheHit,
          summary.cacheMiss,
          summary.renderDeferredLazyLoadCount,
          Phoenix_ResourceStreaming_GetStateName(
              g_PhoenixCreatureWarmupQueue.empty()
                  ? PHOENIX_RESOURCE_STREAM_STATE_READY
                  : PHOENIX_RESOURCE_STREAM_STATE_QUEUED));

  fclose(qfp);
}

void Phoenix_CreatureWarmup_ResetSummary()
{
  memset(&g_PhoenixCreatureWarmupSummary, 0, sizeof(g_PhoenixCreatureWarmupSummary));
  g_PhoenixCreatureWarmupSummary.queueSizeBegin =
      (unsigned int)g_PhoenixCreatureWarmupQueue.size();
  g_PhoenixCreatureWarmupSummary.queueSizeEnd =
      (unsigned int)g_PhoenixCreatureWarmupQueue.size();
  g_PhoenixCreatureWarmupSummary.budgetMs = 1.0;
}

int Phoenix_ItemOutputPerf_SelectTopStage(const double* stageMs)
{
  int bestStage = -1;
  double bestMs = -1.0;
  for (int i = 0; i < PHOENIX_ITEM_STAGE_COUNT; ++i)
  {
    if (stageMs[i] > bestMs)
    {
      bestMs = stageMs[i];
      bestStage = i;
    }
  }
  return bestStage;
}

void Phoenix_ItemOutputPerf_RecordTopItem(double itemMs, int topStage)
{
  PhoenixItemOutputFrame& frame = g_PhoenixItemOutputFrame;
  if (itemMs <= 0.0)
    return;

  int slot = -1;
  for (int i = 0; i < 10; ++i)
  {
    if (itemMs > frame.topItems[i].ms)
    {
      slot = i;
      break;
    }
  }
  if (slot < 0)
    return;

  for (int i = 9; i > slot; --i)
    frame.topItems[i] = frame.topItems[i - 1];

  frame.topItems[slot].itemID = frame.currentItemID;
  frame.topItems[slot].itemClass = frame.currentItemClass;
  frame.topItems[slot].itemType = frame.currentItemType;
  frame.topItems[slot].itemDrawSpriteKey = frame.currentItemDrawSpriteKey;
  frame.topItems[slot].itemVisualSpriteKey = frame.currentItemVisualSpriteKey;
  frame.topItems[slot].spkResourceKey = frame.currentItemSpkResourceKey;
  frame.topItems[slot].spkPartKey = frame.currentItemSpkPartKey;
  frame.topItems[slot].loadedSpriteKey = frame.currentItemLoadedSpriteKey;
  frame.topItems[slot].warmupSpriteKey = frame.currentItemWarmupSpriteKey;
  frame.topItems[slot].renderSpriteKey = frame.currentItemRenderSpriteKey;
  frame.topItems[slot].stage = topStage;
  frame.topItems[slot].ms = itemMs;
  memcpy(frame.topItems[slot].stageMs,
         frame.currentItemStageMs,
         sizeof(frame.topItems[slot].stageMs));
  frame.topItems[slot].partCount = frame.currentItemPartCount;
  memcpy(frame.topItems[slot].partStageMs,
         frame.currentItemPartStageMs,
         sizeof(frame.topItems[slot].partStageMs));
}

void Phoenix_ItemOutputPerf_AddPartStageMs(int stage, double ms)
{
  PhoenixItemOutputFrame& frame = g_PhoenixItemOutputFrame;
  if (!frame.active || !frame.currentItemActive || ms <= 0.0)
    return;
  if (stage < 0 || stage >= PHOENIX_ITEM_PART_STAGE_COUNT)
    return;

  frame.currentItemPartStageMs[stage] += ms;
}

int Phoenix_ItemOutputPerf_MapItemStageToPartStage(int stage)
{
  switch (stage)
  {
    case PHOENIX_ITEM_STAGE_RESOLVE_KEY:
      return PHOENIX_ITEM_PART_STAGE_KEY_RESOLVE;
    case PHOENIX_ITEM_STAGE_RESOURCE_CHECK:
    case PHOENIX_ITEM_STAGE_TEXTURE_GET:
    case PHOENIX_ITEM_STAGE_SPK_CACHE_HIT:
    case PHOENIX_ITEM_STAGE_SPK_CACHE_MISS:
      return PHOENIX_ITEM_PART_STAGE_CACHE_LOOKUP;
    case PHOENIX_ITEM_STAGE_WARMUP_CHECK:
      return PHOENIX_ITEM_PART_STAGE_RESOURCE_PREPARE;
    case PHOENIX_ITEM_STAGE_LAZY_TEXTURE_INIT:
      return PHOENIX_ITEM_PART_STAGE_RESOURCE_CREATE;
    case PHOENIX_ITEM_STAGE_SPK_LOAD:
      return PHOENIX_ITEM_PART_STAGE_SPK_DECODE;
    case PHOENIX_ITEM_STAGE_SURFACE_COPY:
      return PHOENIX_ITEM_PART_STAGE_SURFACE_COPY;
    case PHOENIX_ITEM_STAGE_SURFACE_BLT:
      return PHOENIX_ITEM_PART_STAGE_SURFACE_BLT;
    case PHOENIX_ITEM_STAGE_SURFACE_LOCK:
      return PHOENIX_ITEM_PART_STAGE_LOCK;
    case PHOENIX_ITEM_STAGE_SURFACE_UNLOCK:
      return PHOENIX_ITEM_PART_STAGE_UNLOCK;
    default:
      return -1;
  }
}

void Phoenix_ItemOutputPerf_AddStageMs(int stage, double ms)
{
  if (!g_PhoenixItemOutputFrame.active || ms <= 0.0)
    return;
  if (stage < 0 || stage >= PHOENIX_ITEM_STAGE_COUNT)
    return;

  g_PhoenixItemOutputFrame.stageMs[stage] += ms;
  if (g_PhoenixItemOutputFrame.currentItemActive)
  {
    g_PhoenixItemOutputFrame.currentItemStageMs[stage] += ms;
    if (g_PhoenixItemOutputPartLoopDepth > 0)
      Phoenix_ItemOutputPerf_AddPartStageMs(
          Phoenix_ItemOutputPerf_MapItemStageToPartStage(stage), ms);
  }
}

void Phoenix_ItemOutputPerf_RecordStageLocalSpkLazyLoad(int stage, double ms)
{
  if (!g_PhoenixItemOutputFrame.active || ms <= 0.0)
    return;
  if (stage < 0 || stage >= PHOENIX_RENDER_LAZY_STAGE_COUNT)
    return;

  g_PhoenixItemOutputFrame.stageSpkLazyLoadCount[stage]++;
  g_PhoenixItemOutputFrame.stageSpkLazyLoadMs[stage] += ms;
}

void Phoenix_ItemOutputPerf_RecordRenderFallback(int spriteID, double ms, int stage)
{
  PhoenixItemOutputFrame& frame = g_PhoenixItemOutputFrame;
  if (!frame.active || !frame.currentItemActive || ms <= 0.0 ||
      g_PhoenixRenderLazyGuard.stage != PHOENIX_RENDER_LAZY_STAGE_ITEM_OUTPUT)
    return;

  frame.renderFallbackLazyLoadCount++;
  frame.renderFallbackLazyLoadMs += ms;
  frame.renderFallbackLazyLoadSpriteKey = spriteID;
  frame.renderFallbackLazyLoadItemID = frame.currentItemID;
  frame.renderFallbackLazyLoadStage = stage;

  if (frame.currentItemSpriteKey < 0)
    frame.currentItemSpriteKey = spriteID;
  if (frame.currentItemLoadedSpriteKey < 0)
    frame.currentItemLoadedSpriteKey = spriteID;
  if (frame.currentItemRenderSpriteKey < 0)
    frame.currentItemRenderSpriteKey = spriteID;
}

