double Phoenix_ItemOutputPerf_PartKnownMs(const double* partMs)
{
  double known = 0.0;
  for (int i = 0; i < PHOENIX_ITEM_PART_STAGE_COUNT; ++i)
  {
    if (i == PHOENIX_ITEM_PART_STAGE_TOTAL ||
        i == PHOENIX_ITEM_PART_STAGE_DRAW ||
        i == PHOENIX_ITEM_PART_STAGE_UNKNOWN)
    {
      continue;
    }
    known += partMs[i];
  }
  return known;
}

double Phoenix_ItemOutputPerf_PartDrawMs(const double* partMs)
{
  const double drawMs = partMs[PHOENIX_ITEM_PART_STAGE_TOTAL] -
                        Phoenix_ItemOutputPerf_PartKnownMs(partMs);
  return drawMs > 0.0 ? drawMs : 0.0;
}

const char* Phoenix_ItemOutputPerf_SelectDominantPartStageName(const double* partMs)
{
  double bestMs = Phoenix_ItemOutputPerf_PartDrawMs(partMs);
  int bestStage = PHOENIX_ITEM_PART_STAGE_DRAW;
  for (int i = 0; i < PHOENIX_ITEM_PART_STAGE_COUNT; ++i)
  {
    if (i == PHOENIX_ITEM_PART_STAGE_TOTAL ||
        i == PHOENIX_ITEM_PART_STAGE_DRAW ||
        i == PHOENIX_ITEM_PART_STAGE_UNKNOWN)
    {
      continue;
    }
    if (partMs[i] > bestMs)
    {
      bestMs = partMs[i];
      bestStage = i;
    }
  }
  return kPhoenixItemPartStageNames[bestStage];
}

void Phoenix_ItemOutputPerf_InsertNoLogTopItem(const PhoenixItemOutputCost& item)
{
  if (item.ms <= 0.0)
    return;

  PhoenixItemOutputNoLogPeriod& period = g_PhoenixItemOutputNoLogPeriod;
  int slot = -1;
  for (int i = 0; i < 10; ++i)
  {
    if (item.ms > period.topItems[i].ms)
    {
      slot = i;
      break;
    }
  }
  if (slot < 0)
    return;

  for (int i = 9; i > slot; --i)
    period.topItems[i] = period.topItems[i - 1];
  period.topItems[slot] = item;
}

void Phoenix_ItemOutputPerf_AddFrameToNoLogPeriod(const PhoenixItemOutputFrame& frame)
{
  PhoenixItemOutputNoLogPeriod& period = g_PhoenixItemOutputNoLogPeriod;
  period.frames++;
  period.itemFrames += frame.itemCount;
  period.mainRowsTotalMs += frame.stageMs[PHOENIX_ITEM_STAGE_MAINROWS];
  period.itemOutputTotalMs += frame.stageMs[PHOENIX_ITEM_STAGE_DRAW_TOTAL];
  if (frame.stageMs[PHOENIX_ITEM_STAGE_MAINROWS] > period.maxMainRowsMs)
    period.maxMainRowsMs = frame.stageMs[PHOENIX_ITEM_STAGE_MAINROWS];
  if (frame.stageMs[PHOENIX_ITEM_STAGE_DRAW_TOTAL] > period.maxItemOutputMs)
    period.maxItemOutputMs = frame.stageMs[PHOENIX_ITEM_STAGE_DRAW_TOTAL];
  if (frame.stageMs[PHOENIX_ITEM_STAGE_DRAW_TOTAL] > 10.0)
    period.itemOutputOver10++;
  if (frame.stageMs[PHOENIX_ITEM_STAGE_DRAW_TOTAL] > 20.0)
    period.itemOutputOver20++;
  if (frame.stageMs[PHOENIX_ITEM_STAGE_SPRITE_PART_LOOP] > period.maxItemSpritePartLoopMs)
    period.maxItemSpritePartLoopMs = frame.stageMs[PHOENIX_ITEM_STAGE_SPRITE_PART_LOOP];

  period.resourceWarmupCount += frame.resourceWarmupCount;
  period.resourceWarmupCacheHit += frame.resourceWarmupCacheHit;
  period.resourceWarmupCacheMiss += frame.resourceWarmupCacheMiss;
  period.resourceWarmupMs += frame.resourceWarmupMs;
  period.surfaceBltCount += frame.surfaceBltCount;
  period.surfaceLockCount += frame.surfaceLockCount;
  period.surfaceUnlockCount += frame.surfaceUnlockCount;
  period.spkLazyLoadCount += frame.spkLazyLoadCount;
  period.spkLazyLoadMs += frame.stageMs[PHOENIX_ITEM_STAGE_SPK_LOAD];
  period.renderFallbackLazyLoadCount += frame.renderFallbackLazyLoadCount;
  period.renderFallbackLazyLoadMs += frame.renderFallbackLazyLoadMs;

  for (int i = 0; i < PHOENIX_ITEM_STAGE_COUNT; ++i)
    period.stageMs[i] += frame.stageMs[i];
  for (int i = 0; i < PHOENIX_RENDER_LAZY_STAGE_COUNT; ++i)
  {
    period.stageSpkLazyLoadCount[i] += frame.stageSpkLazyLoadCount[i];
    period.stageSpkLazyLoadMs[i] += frame.stageSpkLazyLoadMs[i];
  }

  for (int i = 0; i < 10; ++i)
    Phoenix_ItemOutputPerf_InsertNoLogTopItem(frame.topItems[i]);

  if (period.topItems[0].ms > 0.0)
  {
    const PhoenixItemOutputCost& item = period.topItems[0];
    period.maxItemID = item.itemID;
    period.maxItemClass = item.itemClass;
    period.maxItemType = item.itemType;
    period.maxDrawSpriteKey = item.itemDrawSpriteKey;
    period.maxVisualSpriteKey = item.itemVisualSpriteKey;
    period.maxSpkResourceKey = item.spkResourceKey;
    period.maxSpkPartKey = item.spkPartKey;
    period.maxPartCount = item.partCount;
    memcpy(period.maxItemPartStageMs, item.partStageMs, sizeof(period.maxItemPartStageMs));
  }
}

void Phoenix_ItemOutputPerf_ResetNoLogPeriod()
{
  memset(&g_PhoenixItemOutputNoLogPeriod, 0, sizeof(g_PhoenixItemOutputNoLogPeriod));
  memset(g_PhoenixRenderLazyNoLogStages, 0, sizeof(g_PhoenixRenderLazyNoLogStages));
}

void Phoenix_RenderLazyGuard_WriteNoLogSummaryCsv()
{
  const bool fileAlreadyExists = Phoenix_ItemOutputPerf_FileExists("render_lazyload_summary_fix.csv");
  FILE* fp = fopen("render_lazyload_summary_fix.csv", "a");
  if (!fp)
    return;

  if (!fileAlreadyExists)
  {
    fprintf(fp,
            "tick,stage,count,total_ms,max_ms,max_frame_no,max_tick,"
            "max_object_id,max_class,max_type,max_action,max_direction,max_frame,"
            "max_sprite_key,max_resource_key,max_caller_function\n");
  }

  const DWORD tick = GetTickCount();
  for (int stage = 0; stage < PHOENIX_RENDER_LAZY_STAGE_COUNT; ++stage)
  {
    const PhoenixRenderLazyNoLogStage& summary = g_PhoenixRenderLazyNoLogStages[stage];
    if (summary.count == 0)
      continue;
    fprintf(fp,
            "%lu,%s,%u,%.4f,%.4f,%lu,%lu,%lu,%d,%d,%d,%d,%d,%d,%d,%s\n",
            tick,
            Phoenix_RenderLazyGuard_GetStageName(stage),
            summary.count,
            summary.totalMs,
            summary.maxMs,
            summary.maxFrameNo,
            (unsigned long)summary.maxTick,
            (unsigned long)summary.maxObjectID,
            summary.maxClass,
            summary.maxType,
            summary.maxAction,
            summary.maxDirection,
            summary.maxFrame,
            summary.maxSpriteKey,
            summary.maxResourceKey,
            summary.maxCallerFunction ? summary.maxCallerFunction : "");
  }

  fclose(fp);
}

