extern "C" void Phoenix_ItemOutputPerf_BeginFrame(int visibleTileCount, int imageMapSize)
{
  if (!Phoenix_ItemOutputPerf_IsEnabled())
  {
    g_PhoenixItemOutputFrame.active = false;
    g_PhoenixItemOutputFrame.currentItemActive = false;
    return;
  }

  memset(&g_PhoenixItemOutputFrame, 0, sizeof(g_PhoenixItemOutputFrame));
  g_PhoenixItemOutputFrame.active = true;
  g_PhoenixItemOutputFrame.currentItemSpriteKey = -1;
  g_PhoenixItemOutputFrame.currentItemDrawSpriteKey = -1;
  g_PhoenixItemOutputFrame.currentItemVisualSpriteKey = -1;
  g_PhoenixItemOutputFrame.currentItemSpkResourceKey = -1;
  g_PhoenixItemOutputFrame.currentItemSpkPartKey = -1;
  g_PhoenixItemOutputFrame.currentItemLoadedSpriteKey = -1;
  g_PhoenixItemOutputFrame.currentItemWarmupSpriteKey = -1;
  g_PhoenixItemOutputFrame.currentItemRenderSpriteKey = -1;
  g_PhoenixItemOutputFrame.currentItemPartCount = 0;
  g_PhoenixItemOutputFrame.maxSingleItemSpriteKey = -1;
  g_PhoenixItemOutputFrame.maxSingleItemDrawSpriteKey = -1;
  g_PhoenixItemOutputFrame.maxSingleItemSpkResourceKey = -1;
  g_PhoenixItemOutputFrame.renderFallbackLazyLoadSpriteKey = -1;
  g_PhoenixItemOutputFrame.renderFallbackLazyLoadStage = -1;
  g_PhoenixItemOutputFrame.resourceWarmupSpriteKey = -1;
  g_PhoenixItemOutputFrame.visibleTileCount = visibleTileCount;
  g_PhoenixItemOutputFrame.imageMapSizeAtBegin = imageMapSize;
  g_PhoenixItemOutputFrame.resourceWarmupCount = g_PhoenixItemOutputPendingWarmupCount;
  g_PhoenixItemOutputFrame.resourceWarmupCacheHit = g_PhoenixItemOutputPendingWarmupCacheHit;
  g_PhoenixItemOutputFrame.resourceWarmupCacheMiss = g_PhoenixItemOutputPendingWarmupCacheMiss;
  g_PhoenixItemOutputFrame.resourceWarmupMs = g_PhoenixItemOutputPendingWarmupMs;
  g_PhoenixItemOutputFrame.resourceWarmupSpriteKey = g_PhoenixItemOutputPendingWarmupSpriteKey;
  g_PhoenixItemOutputFrame.resourceWarmupItemID = g_PhoenixItemOutputPendingWarmupItemID;
  g_PhoenixItemOutputFrame.resourceWarmupReason = g_PhoenixItemOutputPendingWarmupReason;
  g_PhoenixItemOutputPendingWarmupCount = 0;
  g_PhoenixItemOutputPendingWarmupCacheHit = 0;
  g_PhoenixItemOutputPendingWarmupCacheMiss = 0;
  g_PhoenixItemOutputPendingWarmupMs = 0.0;
  g_PhoenixItemOutputPendingWarmupSpriteKey = -1;
  g_PhoenixItemOutputPendingWarmupItemID = 0;
  g_PhoenixItemOutputPendingWarmupReason = PHOENIX_ITEM_WARMUP_REASON_NONE;
}

extern "C" void Phoenix_ItemOutputPerf_EndFrame()
{
  PhoenixItemOutputFrame& frame = g_PhoenixItemOutputFrame;
  if (!frame.active)
    return;

  frame.active = false;
  frame.currentItemActive = false;
  frame.totalMs = frame.stageMs[PHOENIX_ITEM_STAGE_MAINROWS];

  Phoenix_ItemOutputPerf_AddFrameToNoLogPeriod(frame);

  DWORD now = GetTickCount();
  if (g_PhoenixItemOutputNoLogLastFlushMs == 0)
    g_PhoenixItemOutputNoLogLastFlushMs = now;

  if (now - g_PhoenixItemOutputNoLogLastFlushMs >= 5000)
  {
    Phoenix_ItemOutputPerf_FlushNoLogCsv();
    g_PhoenixItemOutputNoLogLastFlushMs = now;
  }
}

extern "C" unsigned __int64 Phoenix_ItemOutputPerf_Begin()
{
  if (!g_PhoenixItemOutputFrame.active && !Phoenix_RenderLazyGuard_IsActive())
    return 0;
  return Phoenix_ItemOutputPerf_Now();
}

extern "C" void Phoenix_ItemOutputPerf_AddStageTicks(int stage, unsigned __int64 beginTick)
{
  if (!g_PhoenixItemOutputFrame.active || beginTick == 0)
    return;
  if (stage < 0 || stage >= PHOENIX_ITEM_STAGE_COUNT)
    return;

  double ms = Phoenix_ItemOutputPerf_TicksToMs(Phoenix_ItemOutputPerf_Now() - beginTick);
  Phoenix_ItemOutputPerf_AddStageMs(stage, ms);
}

extern "C" void Phoenix_ItemOutputPerf_BeginItem(TYPE_OBJECTID itemID, int itemClass, int itemType)
{
  PhoenixItemOutputFrame& frame = g_PhoenixItemOutputFrame;
  if (!frame.active)
    return;

  frame.currentItemActive = true;
  frame.currentItemID = itemID;
  frame.currentItemClass = itemClass;
  frame.currentItemType = itemType;
  frame.currentItemSpriteKey = -1;
  frame.currentItemDrawSpriteKey = -1;
  frame.currentItemVisualSpriteKey = -1;
  frame.currentItemSpkResourceKey = -1;
  frame.currentItemSpkPartKey = -1;
  frame.currentItemLoadedSpriteKey = -1;
  frame.currentItemWarmupSpriteKey = -1;
  frame.currentItemRenderSpriteKey = -1;
  frame.currentItemPartCount = 0;
  frame.currentItemBeginTick = Phoenix_ItemOutputPerf_Now();
  memset(frame.currentItemStageMs, 0, sizeof(frame.currentItemStageMs));
  memset(frame.currentItemPartStageMs, 0, sizeof(frame.currentItemPartStageMs));
  frame.itemCount++;
}

extern "C" void Phoenix_ItemOutputPerf_EndItem()
{
  PhoenixItemOutputFrame& frame = g_PhoenixItemOutputFrame;
  if (!frame.active || !frame.currentItemActive || frame.currentItemBeginTick == 0)
    return;

  const double itemMs =
      Phoenix_ItemOutputPerf_TicksToMs(Phoenix_ItemOutputPerf_Now() - frame.currentItemBeginTick);
  const int topStage = Phoenix_ItemOutputPerf_SelectTopStage(frame.currentItemStageMs);

  if (itemMs > frame.maxSingleItemMs)
  {
    frame.maxSingleItemMs = itemMs;
    frame.maxSingleItemID = frame.currentItemID;
    frame.maxSingleItemClass = frame.currentItemClass;
    frame.maxSingleItemType = frame.currentItemType;
    frame.maxSingleItemSpriteKey = frame.currentItemSpriteKey;
    frame.maxSingleItemDrawSpriteKey = frame.currentItemDrawSpriteKey;
    frame.maxSingleItemSpkResourceKey = frame.currentItemSpkResourceKey;
    frame.maxSingleItemStage = topStage;
  }

  Phoenix_ItemOutputPerf_RecordTopItem(itemMs, topStage);
  frame.currentItemActive = false;
}

extern "C" void Phoenix_ItemOutputPerf_SetItemSpriteKey(int spriteKey)
{
  Phoenix_ItemOutputPerf_SetItemSpriteKeys(spriteKey, spriteKey, spriteKey, spriteKey, -1, -1, spriteKey);
}

extern "C" void Phoenix_ItemOutputPerf_SetCurrentItemPartCount(int partCount)
{
  if (!g_PhoenixItemOutputFrame.active || !g_PhoenixItemOutputFrame.currentItemActive)
    return;
  g_PhoenixItemOutputFrame.currentItemPartCount = partCount > 0 ? partCount : 0;
}

extern "C" void Phoenix_ItemOutputPerf_BeginPartLoop()
{
  if (g_PhoenixItemOutputFrame.active && g_PhoenixItemOutputFrame.currentItemActive)
    ++g_PhoenixItemOutputPartLoopDepth;
}

extern "C" void Phoenix_ItemOutputPerf_EndPartLoop(unsigned __int64 beginTick)
{
  if (g_PhoenixItemOutputPartLoopDepth > 0)
    --g_PhoenixItemOutputPartLoopDepth;
  if (!g_PhoenixItemOutputFrame.active ||
      !g_PhoenixItemOutputFrame.currentItemActive ||
      beginTick == 0)
  {
    return;
  }

  const double ms = Phoenix_ItemOutputPerf_TicksToMs(
      Phoenix_ItemOutputPerf_Now() - beginTick);
  Phoenix_ItemOutputPerf_AddStageMs(PHOENIX_ITEM_STAGE_SPRITE_PART_LOOP, ms);
  Phoenix_ItemOutputPerf_AddPartStageMs(PHOENIX_ITEM_PART_STAGE_TOTAL, ms);
}

extern "C" void Phoenix_ItemOutputPerf_SetItemSpriteKeys(int drawSpriteKey, int visualSpriteKey,
                                                         int spkResourceKey, int spkPartKey,
                                                         int loadedSpriteKey, int warmupSpriteKey,
                                                         int renderSpriteKey)
{
  PhoenixItemOutputFrame& frame = g_PhoenixItemOutputFrame;
  if (!frame.active || !frame.currentItemActive)
    return;

  if (drawSpriteKey >= 0)
  {
    frame.currentItemSpriteKey = drawSpriteKey;
    frame.currentItemDrawSpriteKey = drawSpriteKey;
  }
  if (visualSpriteKey >= 0)
    frame.currentItemVisualSpriteKey = visualSpriteKey;
  if (spkResourceKey >= 0)
    frame.currentItemSpkResourceKey = spkResourceKey;
  if (spkPartKey >= 0)
    frame.currentItemSpkPartKey = spkPartKey;
  if (loadedSpriteKey >= 0)
    frame.currentItemLoadedSpriteKey = loadedSpriteKey;
  if (warmupSpriteKey >= 0)
    frame.currentItemWarmupSpriteKey = warmupSpriteKey;
  if (renderSpriteKey >= 0)
    frame.currentItemRenderSpriteKey = renderSpriteKey;
}

extern "C" void Phoenix_ItemOutputPerf_RecordSurfaceBlt(unsigned __int64 beginTick)
{
  if (!g_PhoenixItemOutputFrame.active || beginTick == 0)
    return;
  g_PhoenixItemOutputFrame.surfaceBltCount++;
  Phoenix_ItemOutputPerf_AddStageTicks(PHOENIX_ITEM_STAGE_SURFACE_BLT, beginTick);
}

extern "C" void Phoenix_ItemOutputPerf_RecordSurfaceLock(unsigned __int64 beginTick)
{
  if (!g_PhoenixItemOutputFrame.active || beginTick == 0)
    return;
  g_PhoenixItemOutputFrame.surfaceLockCount++;
  Phoenix_ItemOutputPerf_AddStageTicks(PHOENIX_ITEM_STAGE_SURFACE_LOCK, beginTick);
}

extern "C" void Phoenix_ItemOutputPerf_RecordSurfaceUnlock(unsigned __int64 beginTick)
{
  if (!g_PhoenixItemOutputFrame.active || beginTick == 0)
    return;
  g_PhoenixItemOutputFrame.surfaceUnlockCount++;
  Phoenix_ItemOutputPerf_AddStageTicks(PHOENIX_ITEM_STAGE_SURFACE_UNLOCK, beginTick);
}

extern "C" void Phoenix_ItemOutputPerf_RecordTextureGet(int spriteID, unsigned __int64 beginTick)
{
  if (!g_PhoenixItemOutputFrame.active ||
      !g_PhoenixItemOutputFrame.currentItemActive ||
      beginTick == 0)
    return;
  g_PhoenixItemOutputFrame.textureGetCount++;
  if (g_PhoenixItemOutputFrame.currentItemActive)
    Phoenix_ItemOutputPerf_SetItemSpriteKeys(-1, -1, spriteID, spriteID, -1, -1, spriteID);
  Phoenix_ItemOutputPerf_AddStageTicks(PHOENIX_ITEM_STAGE_TEXTURE_GET, beginTick);
}

extern "C" void Phoenix_ItemOutputPerf_RecordLazyTexture(int spriteID, unsigned __int64 beginTick)
{
  if (beginTick == 0)
    return;
  const double ms = Phoenix_ItemOutputPerf_TicksToMs(Phoenix_ItemOutputPerf_Now() - beginTick);
  Phoenix_RenderLazyGuard_WriteCsv(spriteID, ms, "TextureCreate");
  if (g_PhoenixOutputMapFrame.active)
    g_PhoenixOutputMapFrame.surfaceCreateMs += ms;
  if (!g_PhoenixItemOutputFrame.active || !g_PhoenixItemOutputFrame.currentItemActive)
    return;
  g_PhoenixItemOutputFrame.lazyTextureLoadCount++;
  g_PhoenixItemOutputFrame.textureCreateCount++;
  Phoenix_ItemOutputPerf_SetItemSpriteKeys(-1, -1, spriteID, spriteID, spriteID, -1, spriteID);
  Phoenix_ItemOutputPerf_AddStageMs(PHOENIX_ITEM_STAGE_LAZY_TEXTURE_INIT, ms);
  Phoenix_ItemOutputPerf_RecordRenderFallback(spriteID, ms, PHOENIX_ITEM_STAGE_LAZY_TEXTURE_INIT);
}

extern "C" void Phoenix_ItemOutputPerf_RecordSpkLazyLoad(int spriteID, unsigned __int64 beginTick)
{
  if (beginTick == 0)
    return;
  const double ms = Phoenix_ItemOutputPerf_TicksToMs(Phoenix_ItemOutputPerf_Now() - beginTick);
  Phoenix_RenderLazyGuard_RecordSummary(spriteID, ms, "CTypePack::SPKLazyLoad");
  Phoenix_RenderLazyGuard_WriteCsv(spriteID, ms, "SpkLazyLoad");
  Phoenix_ItemOutputPerf_RecordStageLocalSpkLazyLoad(g_PhoenixRenderLazyGuard.stage, ms);
  if (g_PhoenixOutputMapFrame.active)
    g_PhoenixOutputMapFrame.spkLazyLoadMs += ms;
  if (!g_PhoenixItemOutputFrame.active || !g_PhoenixItemOutputFrame.currentItemActive)
    return;
  if (g_PhoenixRenderLazyGuard.stage != PHOENIX_RENDER_LAZY_STAGE_ITEM_OUTPUT)
    return;

  g_PhoenixItemOutputFrame.spkLazyLoadCount++;
  Phoenix_ItemOutputPerf_SetItemSpriteKeys(-1, -1, spriteID, spriteID, spriteID, -1, spriteID);
  Phoenix_ItemOutputPerf_AddStageMs(PHOENIX_ITEM_STAGE_SPK_LOAD, ms);
  Phoenix_ItemOutputPerf_RecordRenderFallback(spriteID, ms, PHOENIX_ITEM_STAGE_SPK_LOAD);
}

extern "C" unsigned __int64 Phoenix_ItemOutputPerf_BeginResourceWarmup()
{
  if (!Phoenix_ItemOutputPerf_IsEnabled())
    return 0;
  return Phoenix_ItemOutputPerf_Now();
}

extern "C" void Phoenix_ItemOutputPerf_RecordResourceWarmup(int cacheHit, unsigned __int64 beginTick,
                                                            TYPE_OBJECTID itemID, int spriteKey,
                                                            int reason)
{
  if (beginTick == 0)
    return;

  g_PhoenixItemOutputPendingWarmupCount++;
  g_PhoenixItemOutputPendingWarmupMs +=
      Phoenix_ItemOutputPerf_TicksToMs(Phoenix_ItemOutputPerf_Now() - beginTick);

  if (cacheHit)
    g_PhoenixItemOutputPendingWarmupCacheHit++;
  else
    g_PhoenixItemOutputPendingWarmupCacheMiss++;

  g_PhoenixItemOutputPendingWarmupSpriteKey = spriteKey;
  g_PhoenixItemOutputPendingWarmupItemID = itemID;
  g_PhoenixItemOutputPendingWarmupReason = reason;
  if (spriteKey >= 0)
    g_PhoenixItemOutputWarmupUniqueResources.insert(((DWORD)reason << 24) ^ (DWORD)spriteKey);
}

extern "C" int Phoenix_ItemOutputPerf_IsCurrentItemActive()
{
  return (g_PhoenixItemOutputFrame.active && g_PhoenixItemOutputFrame.currentItemActive) ||
         Phoenix_RenderLazyGuard_IsActive();
}

extern "C" unsigned int Phoenix_ItemOutputPerf_GetWarmupUniqueResourceCount()
{
  return (unsigned int)g_PhoenixItemOutputWarmupUniqueResources.size();
}

