//----------------------------------------------------------------------
// Init
//----------------------------------------------------------------------
// View¿¡ ÇÊ¿äÇÑ °¢ ºÎºÐµéÀº ÃÊ±âÈ­ ½ÃÅ²´Ù.
//----------------------------------------------------------------------
bool MTopView::Init() {
  //------------------------------------------
  // ÀÌ¹Ì initµÆ´Ù¸é initÇÏÁö ¾Ê´Â´Ù.
  //------------------------------------------
  if (m_bInit) {
    return false;
  }

  //----------------------------------------------------------------------
  // ÇÑ filterÁÂÇ¥ÀÇ È­¸éºñÀ² °áÁ¤..
  //----------------------------------------------------------------------
  s_LightWidth = CLIPSURFACE_WIDTH / (float)SCREENLIGHT_WIDTH;
  s_LightHeight = CLIPSURFACE_HEIGHT / (float)SCREENLIGHT_HEIGHT;

  //------------------------------------------
  // ÀûÀýÇÑ Texture Memory °è»ê
  //
  // D3D9 native modda DirectDraw objesi yok. Texture memory bilgisi
  // QueryAvailableVideoMemory helper'i ile D3D9 device'tan alinir; bilgi
  // optionaldir ve sadece texture sayisi heuristic'ini besler.
  //------------------------------------------
  DWORD dwTotal = 0;
  DWORD dwFree  = 0;
  HRESULT hr = CDirectDraw::QueryAvailableVideoMemory(
      DDSCAPS_TEXTURE, &dwTotal, &dwFree);
  if (hr != DD_OK) {
    // Sane defaults — modern GPU'lar 256 MB+. 64 MB conservative.
    dwTotal = 64 * 1024 * 1024;
    dwFree  = 32 * 1024 * 1024;
  }

  DEBUG_ADD_FORMAT("[TextureMemory] Before Init View = %d/%d", dwFree, dwTotal);

  //------------------------------------------
  // ÀûÀýÇÑ effect texture°³¼ö
  //------------------------------------------
  // 1500000Á¤µµ´Â ´Ù¸¥µ¥ »ç¿ëµÈ´Ù°í º»´Ù.
  // Æò±ÕÀûÀÎ ÇÑ TextureÀÇ memory size = 65536 - -;;
  //------------------------------------------
  int freeMemory = dwFree - 1500000;

  if (freeMemory < 0)
    freeMemory = 0;

  int num = freeMemory / 20000 / 12;

  num = max(num, 30); // 30º¸´Ù´Â Ä¿¾ßÇÑ´Ù.
  num = min(num, 60); // 60ÀÌ ÃÖ°í´Ù.

  // num = 20;

  // Àç¼³Á¤.. - -;
  // g_pClientConfig->MAX_TEXTUREPART_EFFECT				=
  // num*3/2; g_pClientConfig->MAX_TEXTUREPART_CREATURESHADOW		= num*3;
  // g_pClientConfig->MAX_TEXTUREPART_IMAGEOBJECTSHADOW	= num;
  // g_pClientConfig->MAX_TEXTUREPART_ADDON_SHADOW			= 240 +
  // num*7;

  //------------------------------------------------------------------------
  // Ä³¸¯ÅÍ ±×¸²ÀÚ¸¦ ¹«Á¶°Ç °Ë°Ô Ãâ·ÂÇÑ´Ù°í ÇßÀ» ¶§ÀÇ °è»ê
  //------------------------------------------------------------------------
  g_pClientConfig->MAX_TEXTUREPART_EFFECT = num * 2;       // num*10;
  g_pClientConfig->MAX_TEXTUREPART_SCREENEFFECT = num * 5; // num*10;
  g_pClientConfig->MAX_TEXTUREPART_CREATURESHADOW = 1;     // num*3;
  g_pClientConfig->MAX_TEXTUREPART_IMAGEOBJECTSHADOW = num * 2;
  g_pClientConfig->MAX_TEXTUREPART_ADDON_SHADOW = 1; // 240 + num*7;

  DEBUG_ADD_FORMAT("[MTopView::TexturePart] AlphaEffect = %d",
                   g_pClientConfig->MAX_TEXTUREPART_EFFECT);
  DEBUG_ADD_FORMAT("[MTopView::TexturePart] ScreenEffect = %d",
                   g_pClientConfig->MAX_TEXTUREPART_SCREENEFFECT);
  DEBUG_ADD_FORMAT("[MTopView::TexturePart] CreatureShadow = %d",
                   g_pClientConfig->MAX_TEXTUREPART_CREATURESHADOW);
  DEBUG_ADD_FORMAT("[MTopView::TexturePart] ImageObjectShadow = %d",
                   g_pClientConfig->MAX_TEXTUREPART_IMAGEOBJECTSHADOW);
  DEBUG_ADD_FORMAT("[MTopView::TexturePart] AddonShadow = %d",
                   g_pClientConfig->MAX_TEXTUREPART_ADDON_SHADOW);

  CT_Done("DIAG: MTopView::Init - Starting sub-initializations");

  bool bSurfaces = InitSurfaces();
  CT_Done("DIAG: InitSurfaces result: %d", bSurfaces);

  bool bColors = InitColors();
  CT_Done("DIAG: InitColors result: %d", bColors);

  bool bSprites = InitSprites();
  CT_Done("DIAG: InitSprites result: %d", bSprites);

  bool bFilters = InitFilters();
  CT_Done("DIAG: InitFilters result: %d", bFilters);

  bool bCreatureFrames = InitCreatureFrames();
  CT_Done("DIAG: InitCreatureFrames result: %d", bCreatureFrames);

  bool bImageFrames = InitImageFrames();
  CT_Done("DIAG: InitImageFrames result: %d", bImageFrames);

  bool bAnimationFrames = InitAnimationFrames();
  CT_Done("DIAG: InitAnimationFrames result: %d", bAnimationFrames);

  bool bEffectFrames = InitEffectFrames();
  CT_Done("DIAG: InitEffectFrames result: %d", bEffectFrames);

  bool bFonts = InitFonts();
  CT_Done("DIAG: InitFonts result: %d", bFonts);

  if (bSurfaces && bColors && bSprites && bFilters && bCreatureFrames &&
      bImageFrames && bAnimationFrames && bEffectFrames && bFonts) {
//------------------------------------------
// ÀûÀýÇÑ Texture Memory °è»ê
//
// D3D9 helper uzerinden texture memory debug bilgisi.
//------------------------------------------
#ifdef OUTPUT_DEBUG
    DWORD dwTotal = 0;
    DWORD dwFree  = 0;
    CT_Done("MTopView::Init - Getting AvailableVidMem (D3D9 helper)");
    HRESULT hr = CDirectDraw::QueryAvailableVideoMemory(
        DDSCAPS_TEXTURE, &dwTotal, &dwFree);
    CT_Done("MTopView::Init - Got VidMem (hr=%d)", hr);

    DEBUG_ADD_FORMAT("[TextureMemory] After Init View = %d/%d", dwFree,
                     dwTotal);
#endif

    m_bInit = true;

    PrecalculateAdvancementClassCreatureFrames();

    return true;
  }

  return false;
}

