//----------------------------------------------------------------------
// Add MonsterSpriteTypes
//----------------------------------------------------------------------
// Hallu¿¡¼­ ÂüÁ¶ÇÏ°Ô µÉ °ÍÀÌ´ç...
//----------------------------------------------------------------------
void MTopView::AddMonsterSpriteTypes(const INT_ORDERED_LIST &listUse) {
  INT_ORDERED_LIST::DATA_LIST::const_iterator iUse = listUse.GetIterator();

  for (int i = 0; i < listUse.GetSize(); i++) {
    int useSpriteType = *iUse;

    if (!Phoenix_IsValidCreatureSpriteType(
            useSpriteType, "MTopView::AddMonsterSpriteTypes")) {
      iUse++;
      continue;
    }

    if ((*g_pCreatureSpriteTable)[useSpriteType].IsMonsterSprite()) {
      m_listLoadedMonsterSprite.Add(useSpriteType);
    }

    iUse++;
  }
}

//----------------------------------------------------------------------
// Release Useless CreatureSPK Except
//----------------------------------------------------------------------
// list´Â »ç¿ëÇÏ´Â creatureµéÀÇ sprite type ÀÌ´Ù.
//----------------------------------------------------------------------
void MTopView::ReleaseUselessCreatureSPKExcept(
    const INT_ORDERED_LIST &listUse) {
  // Áö±ÝÀº ¸÷+NPC ½ºÇÁ¶óÀÌÆ®°¡ ¾ó¸¶ ¾øÀ¸¹Ç·Î releaseÇÏÁö ¾Ê´Â´Ù.
  // return;

  //--------------------------------------------------------
  // loadµÈ °Íµé Áß¿¡¼­ »ç¿ëÁßÀÎ°Å´Â »©°í..
  //--------------------------------------------------------
  m_listLoadedCreatureSprite -= listUse;

  //--------------------------------------------------------
  // ³ª¸ÓÁö´Â Á¦°ÅÇÑ´Ù.
  //--------------------------------------------------------
  INT_ORDERED_LIST::DATA_LIST::const_iterator iSpriteType =
      m_listLoadedCreatureSprite.GetIterator();

  int releasedCount = 0;

  for (int i = 0; i < m_listLoadedCreatureSprite.GetSize(); i++) {
    int spriteType = *iSpriteType;

    if (!Phoenix_IsValidCreatureSpriteType(
            spriteType, "MTopView::ReleaseUselessCreatureSPKExcept.loaded")) {
      iSpriteType++;
      continue;
    }

    //--------------------------------------------------------
    // Player±×¸²ÀÏ°æ¿ì´Â Á¦°ÅÇÏÁö ¾Ê´Â´Ù.
    //--------------------------------------------------------
    // if (spriteType==(*g_pCreatureTable)[CREATURETYPE_SLAYER_MALE].SpriteType
    //	||
    // spriteType==(*g_pCreatureTable)[CREATURETYPE_SLAYER_FEMALE].SpriteType
    //	|| spriteType==(*g_pCreatureTable)[CREATURETYPE_VAMPIRE_MALE].SpriteType
    //	||
    // spriteType==(*g_pCreatureTable)[CREATURETYPE_VAMPIRE_FEMALE].SpriteType
    //	|| spriteType==(*g_pCreatureTable)[CREATURETYPE_WOLF].SpriteType
    //	|| spriteType==(*g_pCreatureTable)[CREATURETYPE_BAT].SpriteType
    //	||
    // spriteType==(*g_pCreatureTable)[CREATURETYPE_SLAYER_OPERATOR].SpriteType
    //	||
    // spriteType==(*g_pCreatureTable)[CREATURETYPE_VAMPIRE_OPERATOR].SpriteType)
    if ((*g_pCreatureSpriteTable)[spriteType].IsPlayerSprite()) {
      DEBUG_ADD_FORMAT("[ReleaseUselessCreatureSPK] Skip spriteType=%d",
                       spriteType);

      iSpriteType++;
      continue;
    }

    DEBUG_ADD_FORMAT("[ReleaseUselessCreatureSPK] Release spriteType=%d",
                     spriteType);

		if ((*g_pCreatureSpriteTable)[spriteType].bLoad) {
      /*
      int first, last;
      // ÀÌ¹Ì LoadµÈ °æ¿ì
      // n¹øÂ° creatureÀÇ sprite¸¦ ¸Þ¸ð¸® ÇØÁ¦

      //--------------------------------------------------------
      // Creature SPK Á¦°Å
      //--------------------------------------------------------
      first = (*g_pCreatureSpriteTable)[spriteType].FirstSpriteID;
      last = (*g_pCreatureSpriteTable)[spriteType].LastSpriteID;

      if (last > first && first!=SPRITEID_NULL && last!=SPRITEID_NULL)
      {
              m_CreatureSPK.ReleasePart(first, last);
      }

      //--------------------------------------------------------
      // Creature SSPK Á¦°Å
      //--------------------------------------------------------
      first = (*g_pCreatureSpriteTable)[spriteType].FirstSpriteID;
      last = (*g_pCreatureSpriteTable)[spriteType].LastSpriteID;

      if (last > first && first!=SPRITEID_NULL && last!=SPRITEID_NULL)
      {
              m_CreatureSSPK.ReleasePart( first, last );
      }
      */
      // 2026-08-26 ROOT CAUSE: Eski yol ReleaseCreatureSPK(frameID) cagiriyordu.
      // ReleaseCreatureSPK(n) ise n'yi CreatureTable index sanıyor — FrameID !=
      // creatureType. Yanlis tablodan First/Last okunuyor veya hic release yok;
      // bLoad yine FALSE yapilinca sonraki PreLoad AYNI sprite'lari tekrar
      // yukluyor → her zone hop ~100MB+ birikim (dump yok, MODE_QUIT OOM).
      // Duzeltme: spriteType'in kendi First/Last + pack slot ile ReleasePart.
      {
        const TYPE_SPRITEID first =
            (*g_pCreatureSpriteTable)[spriteType].FirstSpriteID;
        const TYPE_SPRITEID last =
            (*g_pCreatureSpriteTable)[spriteType].LastSpriteID;
        const int frameID = (*g_pCreatureSpriteTable)[spriteType].FrameID;

        if (frameID != FRAMEID_NULL &&
            Phoenix_IsValidSpriteRange(first, last)) {
          switch (Phoenix_GetCreatureSpritePackSlot(frameID)) {
          case 1:
            m_CreatureSPK.ReleasePart(first, last);
            break;
          case 2:
            m_CreatureSPK2.ReleasePart(first, last);
            break;
          case 7:
            m_CreatureSPK7.ReleasePart(first, last);
            break;
          default:
            m_CreatureSPK3.ReleasePart(first, last);
            break;
          }
        }

        const TYPE_SPRITEID shadowFirst =
            (*g_pCreatureSpriteTable)[spriteType].FirstShadowSpriteID;
        const TYPE_SPRITEID shadowLast =
            (*g_pCreatureSpriteTable)[spriteType].LastShadowSpriteID;
        if (frameID != FRAMEID_NULL &&
            Phoenix_IsValidSpriteRange(shadowFirst, shadowLast)) {
          if (frameID < 287)
            m_CreatureSSPK.ReleasePart(shadowFirst, shadowLast);
          else if (frameID > 286 && frameID < 402)
            m_CreatureSSPK2.ReleasePart(shadowFirst, shadowLast);
          else
            m_CreatureSSPK3.ReleasePart(shadowFirst, shadowLast);
        }
      }

      // loadÇÏÁö ¾Ê¾Ò´Ù°í Ç¥½ÃÇÑ´Ù.
      (*g_pCreatureSpriteTable)[spriteType].bLoad = FALSE;
      releasedCount++;
    }

    iSpriteType++;
  }

  if (releasedCount > 0) {
    Phoenix_FatalDiagLogf(
        "ReleaseUselessCreatureSPKExcept released=%d keep=%d", releasedCount,
        listUse.GetSize());
  }

  //--------------------------------------------------------
  // loadµÈ °Í ´Ù½Ã ¼³Á¤
  //--------------------------------------------------------
  m_listLoadedCreatureSprite.Release();
  m_listLoadedMonsterSprite.Release();

  INT_ORDERED_LIST::DATA_LIST::const_iterator iUse = listUse.GetIterator();

  for (int i = 0; i < listUse.GetSize(); i++) {
    int useSpriteType = *iUse;

    if (!Phoenix_IsValidCreatureSpriteType(
            useSpriteType, "MTopView::ReleaseUselessCreatureSPKExcept.use")) {
      iUse++;
      continue;
    }

    m_listLoadedCreatureSprite.Add(useSpriteType);

    if ((*g_pCreatureSpriteTable)[useSpriteType].IsMonsterSprite()) {
      m_listLoadedMonsterSprite.Add(useSpriteType);
    }

    iUse++;
  }
}

