//----------------------------------------------------------------------
// PurgeCachedZoneMapSprites
//----------------------------------------------------------------------
// Differential ReleaseTileSPK* 1311<->1321 gibi benzer map'lerde neredeyse
// hic byte bosaltmiyor. Budget/OOM'da:
//  1) SFPA listedeki sprite pixel'leri ReleasePart
//  2) Tum pack uzerinde ReleasePart(0..n) (SFPA bossa bile)
//  3) FileCacheMap ClearFileCache — asil VA sizintisi: split .spk chunk
//     ivfstream = PhoenixProtected tam decrypt buffer (tile~120MB pack,
//     imageobject~474MB). Get() unit tamamlanana kadar cache'te tutuyor.
//----------------------------------------------------------------------
void MTopView::PurgeCachedZoneMapSprites() {
  COrderedList<TYPE_SPRITEID> tileIds;
  COrderedList<TYPE_SPRITEID> imageIds;

  auto collectTiles = [&](CSpriteFilePositionArray *pSFPA) {
    if (pSFPA == NULL)
      return;
    for (int i = (int)pSFPA->GetSize() - 1; i >= 0; --i)
      tileIds.Add((*pSFPA)[i].SpriteID);
  };
  auto collectImages = [&](CSpriteFilePositionArray *pSFPA) {
    if (pSFPA == NULL)
      return;
    for (int i = (int)pSFPA->GetSize() - 1; i >= 0; --i)
      imageIds.Add((*pSFPA)[i].SpriteID);
  };

  collectTiles(m_pTileSFPArrayLargeZone);
  collectTiles(m_pTileSFPArraySmallZone);
  collectImages(m_pImageObjectSFPArrayLargeZone);
  collectImages(m_pImageObjectSFPArraySmallZone);

  auto countPrepared = [](CSpritePack &pack) -> int {
    int n = 0;
    const DWORD sz = pack.GetSize();
    for (DWORD i = 0; i < sz; ++i) {
      if (pack.IsElementPrepared((WORD)i))
        ++n;
    }
    return n;
  };

  const size_t cacheTileBefore = m_TileSPK.GetFileCacheCount();
  const size_t cacheImgBefore = m_ImageObjectSPK.GetFileCacheCount();
  const size_t cacheImgSBefore = m_ImageObjectSSPK.GetFileCacheCount();
  const int tilePrepBefore = countPrepared(m_TileSPK);
  const int imgPrepBefore = countPrepared(m_ImageObjectSPK);

  Phoenix_FatalDiagLogf(
      "PurgeCachedZoneMapSprites enter sfpaTile=%d sfpaImg=%d "
      "fileCache tile=%u img=%u imgs=%u prepared tile=%d img=%d packSize tile=%u img=%u",
      tileIds.GetSize(), imageIds.GetSize(),
      (unsigned)cacheTileBefore, (unsigned)cacheImgBefore,
      (unsigned)cacheImgSBefore, tilePrepBefore, imgPrepBefore,
      (unsigned)m_TileSPK.GetSize(), (unsigned)m_ImageObjectSPK.GetSize());

  if (tileIds.GetSize() > 0)
    m_TileSPK.ReleasePart(tileIds);
  if (imageIds.GetSize() > 0) {
    m_ImageObjectSPK.ReleasePart(imageIds);
    m_ImageObjectSSPK.ReleasePart(imageIds);
  }

  // SFPA differential / bos liste: yine de pack'teki yuklu sprite'lari dusur.
  if (m_TileSPK.GetSize() > 0)
    m_TileSPK.ReleasePart(0, (int)m_TileSPK.GetSize() - 1);
  if (m_ImageObjectSPK.GetSize() > 0)
    m_ImageObjectSPK.ReleasePart(0, (int)m_ImageObjectSPK.GetSize() - 1);
  if (m_ImageObjectSSPK.GetSize() > 0)
    m_ImageObjectSSPK.ReleasePart(0, (int)m_ImageObjectSSPK.GetSize() - 1);

  // Pixel ReleasePart file cache girdilerini de siler ama partial-unit
  // cache (sprite yuklu, unit eksik) kalabilir — kesin temizle.
  m_TileSPK.ClearFileCache();
  m_ImageObjectSPK.ClearFileCache();
  m_ImageObjectSSPK.ClearFileCache();

  // Creature pixel'leri de dusur (yalniz FileCache degil) — PreLoad her hop
  // yeniden yukler; aksi halde CRT high-water + live pack siser.
  if (m_CreatureSPK.GetSize() > 0)
    m_CreatureSPK.ReleasePart(0, (int)m_CreatureSPK.GetSize() - 1);
  if (m_CreatureSPK2.GetSize() > 0)
    m_CreatureSPK2.ReleasePart(0, (int)m_CreatureSPK2.GetSize() - 1);
  if (m_CreatureSPK3.GetSize() > 0)
    m_CreatureSPK3.ReleasePart(0, (int)m_CreatureSPK3.GetSize() - 1);
  if (m_CreatureSPK4.GetSize() > 0)
    m_CreatureSPK4.ReleasePart(0, (int)m_CreatureSPK4.GetSize() - 1);
  if (m_CreatureSPK5.GetSize() > 0)
    m_CreatureSPK5.ReleasePart(0, (int)m_CreatureSPK5.GetSize() - 1);
  if (m_CreatureSPK6.GetSize() > 0)
    m_CreatureSPK6.ReleasePart(0, (int)m_CreatureSPK6.GetSize() - 1);
  if (m_CreatureSPK7.GetSize() > 0)
    m_CreatureSPK7.ReleasePart(0, (int)m_CreatureSPK7.GetSize() - 1);
  m_CreatureSPK.ClearFileCache();
  m_CreatureSPK2.ClearFileCache();
  m_CreatureSPK3.ClearFileCache();
  m_CreatureSPK4.ClearFileCache();
  m_CreatureSPK5.ClearFileCache();
  m_CreatureSPK6.ClearFileCache();
  m_CreatureSPK7.ClearFileCache();
  if (g_pCreatureSpriteTable != NULL) {
    const int nSprite = (int)g_pCreatureSpriteTable->GetSize();
    for (int i = 0; i < nSprite; ++i) {
      if (!(*g_pCreatureSpriteTable)[i].IsPlayerSprite())
        (*g_pCreatureSpriteTable)[i].bLoad = FALSE;
    }
  }
  m_listLoadedCreatureSprite.Release();
  m_listLoadedMonsterSprite.Release();

  delete m_pTileSFPArrayLargeZone;
  m_pTileSFPArrayLargeZone = NULL;
  delete m_pTileSFPArraySmallZone;
  m_pTileSFPArraySmallZone = NULL;
  delete m_pImageObjectSFPArrayLargeZone;
  m_pImageObjectSFPArrayLargeZone = NULL;
  delete m_pImageObjectSFPArraySmallZone;
  m_pImageObjectSFPArraySmallZone = NULL;

  HeapCompact(GetProcessHeap(), 0);
#ifdef _MSC_VER
  _heapmin();
#endif

  Phoenix_FatalDiagLogf(
      "PurgeCachedZoneMapSprites done preparedAfter tile=%d img=%d "
      "fileCacheAfter tile=%u img=%u imgs=%u",
      countPrepared(m_TileSPK), countPrepared(m_ImageObjectSPK),
      (unsigned)m_TileSPK.GetFileCacheCount(),
      (unsigned)m_ImageObjectSPK.GetFileCacheCount(),
      (unsigned)m_ImageObjectSSPK.GetFileCacheCount());

  DEBUG_ADD_FORMAT("PurgeCachedZoneMapSprites tiles=%d images=%d cacheWas=%u/%u/%u prepWas=%d/%d",
                   tileIds.GetSize(), imageIds.GetSize(),
                   (unsigned)cacheTileBefore, (unsigned)cacheImgBefore,
                   (unsigned)cacheImgSBefore, tilePrepBefore, imgPrepBefore);
}

