//----------------------------------------------------------------------
// Add LightFilter To Screen
//----------------------------------------------------------------------
// LightFilter¸¦ Ãß°¡ÇÑ´Ù.
// ScreenÁÂÇ¥¸¦ LightBuffer¿¡ ¸Âµµ·Ï ¹Ù²ã¾ßÇÑ´Ù.
//
// (CLIPSURFACE_WIDTH, CLIPSURFACE_WIDTH)
//  --> (SCREENLIGHT_WIDTH, SCREENLIGHT_HEIGHT)·Î..
//----------------------------------------------------------------------
void MTopView::AddLightFilter2D(int x, int y, BYTE range, bool bMapPixel,
                                bool bForceLight) {
  BYTE originalRange = range;
  if (!bForceLight) {
    range = min(max(g_pPlayer->GetSight() - 3, 0), range);
  }

  if ( // CDirect3D::IsHAL() && m_b3DLight &&
      !g_pPlayer->IsInDarkness() && range != 0 &&
          (m_DarkBits || g_pPlayer->IsInDarkness()) &&
          m_nLight < g_pClientConfig->MAX_LIGHT_DRAW ||
      bForceLight) // ¹«Á¶°Ç Ãâ·ÂÇØ¾ßÇÏ´Â ºû
  {
    // tile ÁÂÇ¥ º¸Á¤
    // x += TILE_X_HALF;
    // y += TILE_Y_HALF;

    // Light FilterÀÇ ¹üÀ§¸¦ ³ÑÁö ¾Êµµ·Ï ÇÑ´Ù.
    if (range >= m_LightFTP.GetSize()) {
      range = m_LightFTP.GetSize() - 1;
    }

    //-----------------------------------------------------
    // range¿¡ µû¶ó¼­ Ãâ·ÂÇÒ lightFilter¸¦ °áÁ¤ÇØ¾ßÇÑ´Ù.
    //-----------------------------------------------------
    int filterID = range;

    static DWORD s_LastVisionAdd2DTrace = 0;
    DWORD now = timeGetTime();
    bool traceVisionAdd = false;
    if (bForceLight && now - s_LastVisionAdd2DTrace > 1000)
    {
      s_LastVisionAdd2DTrace = now;
      traceVisionAdd = true;
    }

    //-----------------------------------------------------
    // LightFilter Ãâ·Â ½ÃÁ¡ °áÁ¤
    /// ±×¸®°í, filterÁÂÇ¥ (fx,fy)·Î ¹Ù²ã¾ß ÇÏ°í..
    // filterÀÇ Áß½ÉÀ» (x,y)¿¡ ¿Àµµ·Ï ¸ÂÃç¾ß ÇÑ´Ù.
    //-----------------------------------------------------
    int fx, fy;

    // (x,y)°¡ ¾î¶² ÁÂÇ¥ÀÎÁö¿¡ µû¶ó¼­ °è»êÀ» ´Ù¸£°Ô ÇØÁØ´Ù.
    if (bMapPixel) {
      // mapPixel --> screen
      POINT screenPoint = PixelToScreen(x, y);

      // screen -> filter
      fx = (float)screenPoint.x / s_LightWidth;
      fy = (float)screenPoint.y / s_LightHeight;
    } else {
      // screen -> filter
      fx = (float)x / s_LightWidth;
      fy = (float)y / s_LightHeight;
    }

    // filter Áß½É ¸ÂÃß±â
    fx = fx - (m_LightFTP[filterID].GetWidth() >> 1);
    fy = fy - (m_LightFTP[filterID].GetHeight() >> 1);

    //-----------------------------------------------------
    // BufferFilter¿¡ Light filter¸¦ Ãß°¡ÇÑ´Ù.
    //-----------------------------------------------------
    int sampleX = fx + (m_LightFTP[filterID].GetWidth() >> 1);
    int sampleY = fy + (m_LightFTP[filterID].GetHeight() >> 1);
    int sampleBefore = -1;
    int sampleAfter = -1;
    int filterCenter = -1;

    if (traceVisionAdd)
    {
      if (sampleX >= 0 && sampleX < m_LightBufferFilter.GetWidth() &&
          sampleY >= 0 && sampleY < m_LightBufferFilter.GetHeight())
      {
        sampleBefore = m_LightBufferFilter.GetFilter((WORD)sampleY)[sampleX];
      }

      int filterCenterX = m_LightFTP[filterID].GetWidth() >> 1;
      int filterCenterY = m_LightFTP[filterID].GetHeight() >> 1;
      if (filterCenterX >= 0 && filterCenterX < m_LightFTP[filterID].GetWidth() &&
          filterCenterY >= 0 && filterCenterY < m_LightFTP[filterID].GetHeight())
      {
        filterCenter = m_LightFTP[filterID].GetFilter((WORD)filterCenterY)[filterCenterX];
      }
    }

    m_LightBufferFilter.BltFilterAdd(fx, fy, m_LightFTP[filterID]);

    if (traceVisionAdd)
    {
      if (sampleX >= 0 && sampleX < m_LightBufferFilter.GetWidth() &&
          sampleY >= 0 && sampleY < m_LightBufferFilter.GetHeight())
      {
        sampleAfter = m_LightBufferFilter.GetFilter((WORD)sampleY)[sampleX];
      }

      CT_BD("[VISION] Add2D x=%d y=%d fx=%d fy=%d origRange=%d range=%d filterID=%d ftpSize=%d map=%d force=%d nLight=%d dark=%d target=%d item=%d sample=(%d,%d) before=%d after=%d filterCenter=%d filterWH=%dx%d bufferWH=%dx%d",
            x, y, fx, fy, (int)originalRange, (int)range, filterID,
            (int)m_LightFTP.GetSize(), bMapPixel ? 1 : 0, bForceLight ? 1 : 0,
            m_nLight, (int)m_DarkBits, (int)m_TargetDarkBits,
            g_pPlayer->GetItemLightSight(), sampleX, sampleY, sampleBefore,
            sampleAfter, filterCenter, (int)m_LightFTP[filterID].GetWidth(),
            (int)m_LightFTP[filterID].GetHeight(),
            (int)m_LightBufferFilter.GetWidth(),
            (int)m_LightBufferFilter.GetHeight());
    }

    m_nLight++;
  }
}

