void MTopView::DrawEventString(int &strX, int &strY) {
  PhoenixTextPerfScope textPerfScope(PHOENIX_TEXT_STAGE_EVENT_TEXT);

  char str[256] = {
      0,
  };
  char str2[256] = {
      0,
  };

  // Delay String
  PrintInfo *pPrintInfo = g_ClientPrintInfo[FONTID_INFO];

  const MEvent *event =
      g_pEventManager->GetEventByFlag(EVENTFLAG_SHOW_DELAY_STRING, 0);

  if (event != NULL) {
    for (int eventMessageCount = 0;
         eventMessageCount <
         (event->m_StringsID.empty() ? 1 : event->m_StringsID.size());
         eventMessageCount++) {
      str[0] = NULL;

      switch (event->eventFlag & EVENTFLAG_SHOW_DELAY_STRING) {
      case EVENTFLAG_SHOW_STRING:
        if (!event->m_StringsID.empty()) {
          if (event->m_StringsID[eventMessageCount] < MAX_GAME_STRING &&
              (*g_pGameStringTable)[event->m_StringsID[eventMessageCount]]
                      .GetString() != NULL)
            strcpy(str,
                   (*g_pGameStringTable)[event->m_StringsID[eventMessageCount]]
                       .GetString());
        }
        break;

      case EVENTFLAG_SHOW_DELAY:
        sprintf(str, "%d",
                (event->eventDelay -
                 (GetTickCount() - event->eventStartTickCount) + 999) /
                    1000);
        break;

      case EVENTFLAG_SHOW_DELAY_STRING:
        if (!event->m_StringsID.empty()) {
          if (event->m_StringsID[eventMessageCount] < MAX_GAME_STRING &&
              (*g_pGameStringTable)[event->m_StringsID[eventMessageCount]]
                      .GetString() != NULL)
            sprintf(str,
                    (*g_pGameStringTable)[event->m_StringsID[eventMessageCount]]
                        .GetString(),
                    (event->eventDelay -
                     (GetTickCount() - event->eventStartTickCount) + 999) /
                        1000);
        }
        break;
      }
      if (str[0] != NULL) {
        const COLORREF color =
            RGB(29 << 3, 29 << 3, 12 << 3); // CDirectDraw::Color(29,8,12);

        const int strWidth = g_GetStringWidth(str, pPrintInfo->hfont) / 2;
        pPrintInfo->text_color = 0;
        g_Print(strX - strWidth + 1, strY + 1, str, pPrintInfo);

        pPrintInfo->text_color = color;
        g_Print(strX - strWidth, strY, str, pPrintInfo);

        strY += 20;
      }
    }
  }

  ZeroMemory(str, 256);
  ZeroMemory(str2, 256);

  // Äù½ºÆ® ºÎºÐÀº Äù½ºÆ® ÀÎÅÍÆäÀÌ½º·Î »«´Ù. ¾Æ·¡ºÎºÐÀº »ç¿ëµÇÁö ¾ÊÀ»µí..
  const MEvent *QuestEvent =
      g_pEventManager->GetEventByFlag(EVENTFLAG_QUEST_INFO, 0);

  if (QuestEvent != NULL) {
    COLORREF color = RGB(116, 243, 73);
    COLORREF color2 = RGB(80, 150, 40);

    str[0] = NULL;
    str2[0] = NULL;

    bool bColor;
    if (QuestEvent->parameter1 > timeGetTime()) {
      if (((QuestEvent->parameter1 - timeGetTime()) / 300) & 0x1)
        bColor = true;
      else
        bColor = false;
    } else {
      bColor = false;
    }

    // if( QuestEvent->parameter1 == 0 )
    {
      QUEST_INFO *mkq = g_pQuestInfoManager->GetInfo(QuestEvent->parameter2);

      if (NULL != mkq) {
        switch (mkq->GetType()) {
        case QUEST_INFO_GATHER_ITEM: {
          // Öğeleri toplamak
          sprintf(str, "I'm collecting items at the moment, lol %d/%d %d",
                  QuestEvent->parameter3, mkq->GetGoal(),
                  QuestEvent->parameter4 - (timeGetTime() / 1000));
        } break;
        case QUEST_INFO_MONSTER_KILL:
          if (QuestEvent->parameter4 <= (timeGetTime() / 1000)) {
            sprintf(str, "%s",
                    (*g_pGameStringTable)
                        [UI_STRING_MESSAGE_EXPIRED_TIME_MONSTER_KILL_QUEST]
                            .GetString());
            color = RGB(255, 181, 181);
            color2 = RGB(255, 181, 181);
          } else if (QuestEvent->parameter3 >= mkq->GetGoal()) {
            sprintf(str, "%s",
                    (*g_pGameStringTable)
                        [UI_STRING_MESSAGE_FINISH_MONSTER_KILL_QUEST]
                            .GetString());
            memset(str2, 0, sizeof(str2));
            DWORD time = QuestEvent->parameter4 - (timeGetTime() / 1000);
            DWORD sec = time % 60;
            DWORD minute = (time / 60) % 60;
            DWORD hour = (time / 60 / 60);
            bool bContinue = false;
            if (hour > 0 || bContinue) {
              bContinue = true;
              char temp[100];
              sprintf(temp,
                      (*g_pGameStringTable)[UI_STRING_MESSAGE_HOUR].GetString(),
                      hour);
              strcat(str2, temp);
              strcat(str2, " ");
            }
            if (minute > 0 || bContinue) {
              bContinue = true;
              char temp[100];
              sprintf(
                  temp,
                  (*g_pGameStringTable)[UI_STRING_MESSAGE_MINUTE].GetString(),
                  minute);
              strcat(str2, temp);
              strcat(str2, " ");
            }
            if (sec > 0 && minute <= 0 && hour <= 0) {
              char temp[100];
              sprintf(
                  temp,
                  (*g_pGameStringTable)[UI_STRING_MESSAGE_SECOND].GetString(),
                  sec);
              strcat(str2, temp);
            }
            // sprintf(str2,"%s",(*g_pGameStringTable)[UI_STRING_MESSAGE_CAN_REQUITAL_FROM_NPC].GetString()
            // );
            strcat(
                str2,
                (*g_pGameStringTable)[UI_STRING_MESSAGE_CAN_REQUITAL_FROM_NPC]
                    .GetString());
            color = RGB(142, 200, 200);
            color2 = RGB(180, 220, 220);
          }

          else {
            sprintf(str, "%s %d/%d ", mkq->GetName(), QuestEvent->parameter3,
                    mkq->GetGoal());
            DWORD time = QuestEvent->parameter4 - (timeGetTime() / 1000);

            DWORD sec = time % 60;
            DWORD minute = (time / 60) % 60;
            DWORD hour = (time / 60 / 60);
            bool bContinue = false;

            if (hour > 0 || bContinue) {
              bContinue = true;
              char temp[100];
              sprintf(temp,
                      (*g_pGameStringTable)[UI_STRING_MESSAGE_HOUR].GetString(),
                      hour);
              strcat(str, temp);
              strcat(str, " ");
            }
            if (minute > 0 || bContinue) {
              bContinue = true;
              char temp[100];
              sprintf(
                  temp,
                  (*g_pGameStringTable)[UI_STRING_MESSAGE_MINUTE].GetString(),
                  minute);
              strcat(str, temp);
              strcat(str, " ");
            }
            if (sec > 0 || bContinue) {
              bContinue = true;
              char temp[100];
              sprintf(
                  temp,
                  (*g_pGameStringTable)[UI_STRING_MESSAGE_SECOND].GetString(),
                  sec);
              strcat(str, temp);
              strcat(str, " ");
            }
          }
          break;
        case QUEST_INFO_MEET_NPC:
          break;
        }
      }
    }

    if (str[0] != NULL) {

      const int strWidth = g_GetStringWidth(str, pPrintInfo->hfont) / 2;
      pPrintInfo->text_color = 0;
      g_Print(strX - strWidth + 1, strY + 1, str, pPrintInfo);

      pPrintInfo->text_color = bColor ? color2 : color;
      g_Print(strX - strWidth, strY, str, pPrintInfo);

      strY += 20;
    }
    if (str2[0] != NULL) {
      const int strWidth = g_GetStringWidth(str2, pPrintInfo->hfont) / 2;
      pPrintInfo->text_color = 0;
      g_Print(strX - strWidth + 1, strY + 1, str2, pPrintInfo);

      pPrintInfo->text_color = bColor ? color2 : color;
      g_Print(strX - strWidth, strY, str2, pPrintInfo);

      strY += 20;
    }
  }
}

