//----------------------------------------------------------------------
// Get Random MonsterType In Zone
//----------------------------------------------------------------------
int MTopView::GetRandomMonsterTypeInZone() const {
  int numSprites = m_listLoadedMonsterSprite.GetSize();

  int spriteType;

  if (numSprites == 0) {
    // ºí·¯µå ¿ö·Ï ±×¸²..
    spriteType = 27;
  } else {
    int nth = rand() % numSprites;

    INT_ORDERED_LIST::DATA_LIST::const_iterator iID =
        m_listLoadedMonsterSprite.GetIterator();

    for (int i = 0; i < nth; i++) {
      iID++;
    }

    spriteType = *iID;
  }

  // spriteID°¡ spriteÀÎ ¸ó½ºÅÍµé Áß¿¡¼­ ÇÏ³ª¸¦ ¼±ÅÃÇÑ´Ù.
  return g_pCreatureSpriteTypeMapper->GetRandomCreatureType(spriteType);
}

void MTopView::DrawCreatureHPModify(POINT *point, MCreature *pCreature) {
  // return;

  if (!g_pPlayer->HasEffectStatus(EFFECTSTATUS_VIEW_HP) ||
      pCreature->IsEmptyHPModifyList())
    return;

  PhoenixTextPerfScope textPerfScope(PHOENIX_TEXT_STAGE_HP_MODIFY);

  MCreature::HPMODIFYLIST *pList =
      (MCreature::HPMODIFYLIST *)pCreature->GetHPModifyList();

  MCreature::HPMODIFYLIST::iterator itr = pList->begin();

  int py = point->y - (pList->size() - 1) * 15;

  g_FL2_GetDC();

  while (itr != pList->end()) {
    char str[128];
    COLORREF color = 0;

    const int modifyValue = itr->modify;
    if (itr->modify < 0) {
      sprintf(str, "%d", modifyValue);
      color = RGB(255, 150, 150);
    } else // rallser ÏÔÊ¾ÉËº¦
    {
      sprintf(str, "+%d", modifyValue);
      // RGB(150, 255, 150);
    }

    g_PrintColorStrOut(
        point->x + TILE_X_HALF -
            g_GetStringWidth(str, gpC_base->m_chatting_pi.hfont) / 2,
        py, str, gpC_base->m_chatting_pi, color, RGB_BLACK);

    py += 15;

    if (GetTickCount() - itr->TickCount > g_pClientConfig->HPModifyListTime) {
      pList->pop_front();
      itr = pList->begin();
    } else
      itr++;
  }

  g_FL2_ReleaseDC();
}
