bool MTopView::ExcuteLostChildPrologue(void *pVoid) {
  MEvent *AdvancementQuestEndingEvent = (MEvent *)pVoid;

  if (AdvancementQuestEndingEvent != NULL) {
    bool bFinEnd = false;

    int SpkIndex = AdvancementQuestEndingEvent->parameter4;
    if (m_AdvacementQuestEnding.GetSize() == 0) {
      // ivfstream	FinFile;
      // if
      // (!FileOpenBinary(g_pFileDef->getProperty("FILE_SPRITE_ADVANCEMENT_QUEST").c_str(),
      // FinFile)) 	return false;
      // m_AdvacementQuestEnding.LoadFromFile(FinFile); FinFile.close();

      if (!m_AdvacementQuestEnding.LoadFromFile(
              g_pFileDef->getProperty("FILE_SPRITE_ADVANCEMENT_QUEST").c_str()))
        return false;
    }
    const TYPE_SOUNDID soundID = SOUND_SLAYER_ENCHANT_B2;

    static BYTE fadeColor[3] = {255, 255, 255};
    static int fadeSpeed = 10;
    static int fadeDirect = 0;
    POINT pointZero = {0, 0};

    if (AdvancementQuestEndingEvent->parameter1 == 0) {
      fadeColor[0] = 255;
      fadeColor[1] = 255;
      fadeColor[2] = 255;
      fadeSpeed = 10;
      fadeDirect = 0;

      // AdvancementQuestEndingEvent->parameter1 =
      // g_pPlayer->IsSlayer()?1000:2000;
      AdvancementQuestEndingEvent->parameter1 = 9998;
      AdvancementQuestEndingEvent->parameter2 = 0;
      AdvancementQuestEndingEvent->parameter3 = 1000;
      //				g_pPlayer->SetChatString((*g_pGameStringTable)[g_pPlayer->IsSlayer()?STRING_MESSAGE_RIPATY_SCRIPT_1:STRING_MESSAGE_AMATA_SCRIPT_1].GetString());
      //
      //				g_pMP3->Stop();
      //				g_pMP3->Open( "Data\\Music\\blood.wav"
      //);

      if (g_DXSound.IsInit()) {
        // 				if( g_pOGG != NULL )
        // 					g_pOGG->streamClose();
        //
        // 				if( g_pSoundBufferForOGG == NULL )
        // 					g_pSoundBufferForOGG = new
        // CDirectSoundBuffer(g_hWnd, SOUND_STEREO, SOUND_44K, SOUND_16BIT);
        //
        // 				if( g_pOGG == NULL )
        // #ifdef _MT
        // 					g_pOGG = new COGGSTREAM(g_hWnd,
        // g_pSoundBufferForOGG, 44100, 11025, 8800); #else
        // g_pOGG = new COGGSTREAM(g_hWnd, g_pSoundBufferForOGG, 44100, 11025,
        // 8800,1); #endif
        //
        // 				if( g_oggfile != NULL)
        // 					fclose(g_oggfile );
        // 				g_oggfile =
        // fopen("data\\music\\Silence_of_Battlefield.ogg","rb");
        // 				g_pOGG->streamLoad(g_oggfile, NULL);
        // 				g_pOGG->streamPlay(SOUND_PLAY_REPEAT);
        // 				int volume = (g_pUserOption->VolumeMusic
        // - 15) * 250; 				g_pOGG->streamVolume(
        // max( -10000, min( -1, volume ) )
        // );

        BGMManager::Instance()->PlayMusic(
            "data\\music\\Silence_of_Battlefield.ogg");
        BGMManager::Instance()->SetVolumeFromSlider(g_pUserOption->VolumeMusic);
      }

      PlaySoundForce(soundID);
      AdvancementQuestEndingEvent->eventStartTickCount = GetTickCount();

      //			g_pBack->Lock();
      //			g_pBack->BltSprite( &pointZero,
      //&m_AdvacementQuestEnding[SpkIndex] ); g_pBack->Unlock();
    }
    //
    m_pSurface->Lock();
    if (AdvancementQuestEndingEvent->parameter3 > 32) {
      m_pSurface->BltSprite(&pointZero, &m_AdvacementQuestEnding[SpkIndex + 1]);
    } else if (AdvancementQuestEndingEvent->parameter3 == 0) {
      m_pSurface->BltSprite(&pointZero, &m_AdvacementQuestEnding[SpkIndex]);
    } else {
      m_pSurface->BltSprite(&pointZero, &m_AdvacementQuestEnding[SpkIndex]);
      m_pSurface->BltSpriteAlpha(&pointZero,
                                 &m_AdvacementQuestEnding[SpkIndex + 1],
                                 AdvancementQuestEndingEvent->parameter3);
    }
    m_pSurface->Unlock();
    if (AdvancementQuestEndingEvent->parameter3 > 0 && g_FrameCount & 0x01)
      AdvancementQuestEndingEvent->parameter3--;
    switch (AdvancementQuestEndingEvent->parameter1) {
    case 9998:
      if (m_pSurface->Lock()) {
        int scroll_progress =
            -500 + (GetTickCount() -
                    AdvancementQuestEndingEvent->eventStartTickCount) /
                       66;
        //				int scroll_progress =
        //-500+(GetTickCount()-AdvancementQuestEndingEvent->eventStartTickCount)/11;

        const int scroll_x =
            SURFACE_WIDTH / 2 - m_AdvacementQuestEnding[0].GetWidth() / 2;
        const int scroll_y = (SURFACE_HEIGHT - 500) / 2;

        /*
        #ifdef CONVERT_1024_768
        #else
                const int scroll_x =
        800/2-m_AdvacementQuestEnding[0].GetWidth()/2, scroll_y = 50; #endif
        */

        int scroll = ((scroll_progress < 0) ? 0 : scroll_progress);
        int scroll2 =
            ((scroll_progress < 0) ? scroll_progress : scroll_progress);
        int scroll3 = ((scroll_progress < 0) ? 500 + scroll_progress : 500);

        Rect rect(
            0, scroll, m_AdvacementQuestEnding[0].GetWidth(),
            min(scroll3, m_AdvacementQuestEnding[0].GetHeight() - scroll));
        S_SURFACEINFO surface_info;
        SetSurfaceInfo(&surface_info, gpC_base->m_p_DDSurface_back->GetDDSD());

        int x = scroll_x, y = scroll_y - scroll2;
        RECT rt;
        rt.left = max(-x, rect.x);
        rt.top = max(-y, rect.y);
        rt.right = min(rect.x + rect.w, SURFACE_WIDTH - x);
        rt.bottom = min(rect.y + rect.h, SURFACE_HEIGHT - y);
        /*
        #ifdef CONVERT_1024_768
        #else
                                        rt.right = min(rect.x+rect.w, 800-x);
                                        rt.bottom = min(rect.y+rect.h, 600-y);
        #endif
        */

        if (rt.bottom < rt.top) {
          AdvancementQuestEndingEvent->parameter1 = 9999;
        }

        if (rt.left < rt.right && rt.top < rt.bottom) {
          WORD *p_dest = (WORD *)surface_info.p_surface + x + rt.left;
          p_dest = (WORD *)((BYTE *)p_dest + (y + rt.top) * surface_info.pitch);

          // void BltClip(WORD *pDest, WORD pitch, RECT* pRect); // in CSprite.h
          m_AdvacementQuestEnding[0].BltClipWidth(p_dest, surface_info.pitch,
                                                  &rt);
        }
        m_pSurface->Unlock();
      }
      break;

    case 9999:
      bFinEnd = true;
      break;
    }

    RECT rect;
    rect.left = 0;
    rect.right = CLIPSURFACE_WIDTH;
    rect.top = 0;
    rect.bottom = CLIPSURFACE_HEIGHT;

    DrawAlphaBox(&rect, fadeColor[0], fadeColor[1], fadeColor[2],
                 min(31, (GetTickCount() -
                          AdvancementQuestEndingEvent->eventStartTickCount) /
                             fadeSpeed) ^
                     fadeDirect);

    if (bFinEnd) {
      //				char szTemp[512];
      //				sprintf(szTemp, "%d",
      //(GetTickCount()-AdvancementQuestEndingEvent->eventStartTickCount)/1000);
      //				UI_AddChatToHistory( szTemp, szTemp, 0,
      // RGB(255, 255, 255) );
      UI_REQUEST_DIE_TIMER_RESET();
      g_pEventManager->RemoveEvent(EVENTID_LOST_CHILD_PROLOGUE);
      m_AdvacementQuestEnding.Release();
    }
    return false;
  }
  return true;
}

