bool MTopView::ExcuteOustersFinEvent() {
  bool bDrawBackGround = true;
  const MEvent *event =
      g_pEventManager->GetEventByFlag(EVENTFLAG_ONLY_EVENT_BACKGROUND);
  if (event != NULL) {
    if ((event->eventFlag & EVENTFLAG_ONLY_EVENT_BACKGROUND) ==
        EVENTFLAG_NOT_DRAW_BACKGROUND) {
      m_pSurface->FillSurface(0); //	È­¸éÁö¿ì±â
    } else if (event->parameter4 < EVENTBACKGROUNDID_MAX) {
      //			AssertEventBackground(event->parameter4);

      POINT p = {0, 0};

      // 2026-05-15 round 4 (root cause fix): EventBackground surface gercek
      // boyutu SURFACE_WIDTH/HEIGHT ile uyumsuz olabilir (1024x768 dosya vs
      // 1280x1024 ekran). CloudRect ile ayni pattern — src rect surface
      // bounds disinda → D3D9Surface::BltNoColorKey manuel memcpy AV.
      // Surface'in kendi GetWidth/GetHeight ile sinirla.
      CDirectDrawSurface *pSurface = g_pEventManager->GetEventBackground(
          (EVENTBACKGROUND_ID)event->parameter4);
      if (pSurface == NULL)
        return bDrawBackGround;
      const int bgW = pSurface->GetWidth();
      const int bgH = pSurface->GetHeight();
      if (bgW <= 0 || bgH <= 0)
        return bDrawBackGround;
      RECT r = {0, 0, bgW, bgH};
      /*
      #ifdef CONVERT_1024_768
      #else
                              RECT r = {0, 0, 799, 599 };
      #endif
      */
      //			if(!m_pSurface->Lock()) return;

      m_pSurface->BltNoColorkey(&p, pSurface, &r);

      //			m_pSurface->BltSprite(&p,
      // g_pEventManager->GetEventBackground(event->parameter4));

      //			m_pSurface->Unlock();
    }

    if (event->eventFlag & EVENTFLAG_ONLY_EVENT_BACKGROUND)
      bDrawBackGround = false;
  }

  MEvent *OustersFinEvent =
      const_cast<MEvent *>(g_pEventManager->GetEvent(EVENTID_OUSTERS_FIN));

  if (OustersFinEvent != NULL) {
    bool bFinEnd = false;

    if (m_OustersFinSPK.GetSize() == 0) {
      // 			ivfstream	FinFile;
      // 			if
      // (!FileOpenBinary(g_pFileDef->getProperty("FILE_SPRITE_OUSTERS_FIN").c_str(),
      // FinFile)) 				return bDrawBackGround;
      // 			m_OustersFinSPK.LoadFromFile(FinFile);
      // 			FinFile.close();
      if (!m_OustersFinSPK.LoadFromFile(
              g_pFileDef->getProperty("FILE_SPRITE_OUSTERS_FIN").c_str()))
        return false;
    }

    const TYPE_SOUNDID soundID = SOUND_SLAYER_ENCHANT_B2;

    static BYTE fadeColor[3] = {255, 255, 255};
    static int fadeSpeed = 10;
    static int fadeDirect = 0;

    if (OustersFinEvent->parameter1 == 0) {
      fadeColor[0] = 255;
      fadeColor[1] = 255;
      fadeColor[2] = 255;
      fadeSpeed = 10;
      fadeDirect = 0;

      // OustersFinEvent->parameter1 = g_pPlayer->IsSlayer()?1000:2000;
      OustersFinEvent->parameter1 = 9998;
      OustersFinEvent->parameter2 = 0;
      //				g_pPlayer->SetChatString((*g_pGameStringTable)[g_pPlayer->IsSlayer()?STRING_MESSAGE_RIPATY_SCRIPT_1:STRING_MESSAGE_AMATA_SCRIPT_1].GetString());
      //
      //				g_pMP3->Stop();
      //				g_pMP3->Open( "Data\\Music\\blood.wav"
      //);

      if (g_DXSound.IsInit()) {
        // 				if( g_pOGG != NULL )
        // 					g_pOGG->streamClose();
        //
        // 				if( g_pSoundBufferForOGG == NULL )
        // 					g_pSoundBufferForOGG = new
        // CDirectSoundBuffer(g_hWnd, SOUND_STEREO, SOUND_44K, SOUND_16BIT);
        //
        // 				if( g_pOGG == NULL )
        // #ifdef _MT
        // 					g_pOGG = new COGGSTREAM(g_hWnd,
        // g_pSoundBufferForOGG, 44100, 11025, 8800); #else
        // g_pOGG = new COGGSTREAM(g_hWnd, g_pSoundBufferForOGG, 44100, 11025,
        // 8800,1); #endif
        //
        // 				if( g_oggfile != NULL)
        // 					fclose(g_oggfile );
        // 				g_oggfile =
        // fopen("data\\music\\chaos.ogg","rb");
        // g_pOGG->streamLoad(g_oggfile, NULL);
        // g_pOGG->streamPlay(SOUND_PLAY_REPEAT);
        // int volume = (g_pUserOption->VolumeMusic - 15) * 250;
        // g_pOGG->streamVolume( max( -10000, min( -1, volume ) ) );

        BGMManager::Instance()->PlayMusic("data\\music\\chaos.ogg");
        BGMManager::Instance()->SetVolumeFromSlider(g_pUserOption->VolumeMusic);
      }
      PlaySoundForce(soundID);
      OustersFinEvent->eventStartTickCount = GetTickCount();
    }

    switch (OustersFinEvent->parameter1) {
    case 1000: {
      if ((GetTickCount() - OustersFinEvent->eventStartTickCount) / 4000 > 0) {
        OustersFinEvent->parameter2++;
        if (OustersFinEvent->parameter2 > 8) {
          g_pPlayer->ClearChatString();

          if (OustersFinEvent->parameter2 == 9) {
            g_pPlayer->SetDead();
            PlaySoundForce(g_pPlayer->IsFemale() ? SOUND_SLAYER_DIE_FEMALE
                                                 : SOUND_SLAYER_DIE_MALE);
            fadeSpeed = 32 * 4;
            fadeColor[0] = 255;
            fadeColor[1] = 0;
            fadeColor[2] = 0;
          }

          if (OustersFinEvent->parameter2 > 9) {
            fadeColor[0] = 0;
            fadeColor[1] = 0;
            fadeColor[2] = 0;
            fadeDirect = 31;

            if (OustersFinEvent->parameter2 > 10) {
              OustersFinEvent->eventStartTickCount = GetTickCount();
              OustersFinEvent->parameter1 = 9998;
              OustersFinEvent->parameter4 = EVENTBACKGROUNDID_OUSTERS_SLAYER;
              g_pMP3->Play(false);
              fadeDirect = 0;
            }
          }
        } else {
          PlaySoundForce(soundID);
          g_pPlayer->SetChatString(
              (*g_pGameStringTable)[STRING_MESSAGE_RIPATY_SCRIPT_1 +
                                    OustersFinEvent->parameter2]
                  .GetString());
        }

        if (OustersFinEvent->parameter2 < 11)
          OustersFinEvent->eventStartTickCount = GetTickCount();
      }
      if (m_pSurface->Lock()) {
        const int char_plus_x = 10, char_plus_y = 24;

        POINT p[8] = {
            {400 - m_OustersFinSPK[3].GetWidth() / 2 + char_plus_x,
             160 - m_OustersFinSPK[3].GetHeight() + char_plus_y},
            {300 - m_OustersFinSPK[4].GetWidth() / 2 + char_plus_x,
             210 - m_OustersFinSPK[4].GetHeight() + char_plus_y},
            {240 - m_OustersFinSPK[5].GetWidth() / 2 + char_plus_x,
             300 - m_OustersFinSPK[5].GetHeight() + char_plus_y},
            {300 - m_OustersFinSPK[6].GetWidth() / 2 + char_plus_x,
             390 - m_OustersFinSPK[6].GetHeight() + char_plus_y},
            {400 - m_OustersFinSPK[7].GetWidth() / 2 + char_plus_x,
             440 - m_OustersFinSPK[7].GetHeight() + char_plus_y},
            {500 - m_OustersFinSPK[8].GetWidth() / 2 + char_plus_x,
             390 - m_OustersFinSPK[8].GetHeight() + char_plus_y},
            {560 - m_OustersFinSPK[9].GetWidth() / 2 + char_plus_x,
             300 - m_OustersFinSPK[9].GetHeight() + char_plus_y},
            {500 - m_OustersFinSPK[10].GetWidth() / 2 + char_plus_x,
             210 - m_OustersFinSPK[10].GetHeight() + char_plus_y},
        };

        m_pSurface->BltSprite(&p[0], &m_OustersFinSPK[3]);
        POINT strPoint = p[0];
        strPoint.x -= 15;
        strPoint.y -= 15;
        DrawChatString(&strPoint, g_pPlayer, RGB(255, 255, 255));

        if (OustersFinEvent->parameter2 > 0) {
          for (int i = 0; i < 7; i++) {
            m_pSurface->BltSprite(&p[i + 1], &m_OustersFinSPK[4 + i]);
          }
        }

        MCreature *pCreature = g_pPlayer;

        int action = pCreature->GetAction(), direction = 6,
            frame = pCreature->GetFrame();

        MCreatureWear *pCreatureWear = (MCreatureWear *)pCreature;

        // CreatureÀÇ Action¿¡ ¸Â´Â add-onÀ» Ãâ·ÂÇÑ´Ù.
        // action = pCreature->GetAction();

        WORD clothes;
        BYTE clothesType;

        for (int i = 0; i < ADDON_MAX; i++) {
          // CreatureÀÇ ÇöÀç ¹æÇâ¿¡ µû¶ó¼­...
          // ¿ÊÀ» Ãâ·ÂÇØÁÖ´Â ¼ø¼­°¡ ´Ù¸¦ ¼ö ÀÖ´Ù.
          clothesType = MCreatureWear::s_AddonOrder[direction][i];

          // i¹øÂ° Á¾·ùÀÇ ¿ÊÀ» ÀÔ°í ÀÖ´Ù¸é Ãâ·ÂÇØ ÁØ´Ù.
          const MCreatureWear::ADDON_INFO &addonInfo =
              pCreatureWear->GetAddonInfo(clothesType);

          if (addonInfo.bAddon) {
#if __CONTENTS(__FAST_TRANSFORTER||__SECOND_TRANSFORTER)
            if (ShouldSkipClassicAddonMotorDraw(addonInfo.ItemClass,
                                                addonInfo.ItemType))
              continue;
#endif //__FAST_TRANSFORTER||__SECOND_TRANSFORTER
            clothes = addonInfo.FrameID;

            CCreatureFramePack &addonFPK =
                pCreatureWear->IsMale() ? m_AddonManFPK : m_AddonWomanFPK;
            CIndexSpritePack &addonSPK =
                pCreatureWear->IsMale() ? m_AddonManSPK : m_AddonWomanSPK;

            FRAME_ARRAY &FA = addonFPK[clothes][action][direction];

            // ÀÖ´Â µ¿ÀÛÀÎ °æ¿ì
            if (FA.GetSize() > frame) {
              CFrame &Frame = FA[frame];
              int sprite =
                  Frame
                      .GetSpriteID(); // m_AddonFPK[clothes][action][direction][frame].GetSpriteID();
              int cx =
                  Frame
                      .GetCX(); // m_AddonFPK[clothes][action][direction][frame].GetCX();
              int cy =
                  Frame
                      .GetCY(); // m_AddonFPK[clothes][action][direction][frame].GetCY();

              CIndexSprite *pSprite = &addonSPK[sprite];

              // º¹ÀåSprite°¡ ÃÊ±âÈ­ µÇÁö ¾ÊÀº °æ¿ì
              //									if
              //(pSprite->IsNotInit())
              //									{
              //										LoadFromFileAddonSPK(
              // clothes, action );
              //									}

              POINT pointTemp;

              // ÁÂÇ¥ º¸Á¤
              pointTemp.x = 384 + cx;
              pointTemp.y = 312 + cy;

              {
                int colorSet1 = addonInfo.ColorSet1,
                    colorSet2 = addonInfo.ColorSet2;
                if (colorSet2 == UNIQUE_ITEM_COLOR ||
                    colorSet2 == QUEST_ITEM_COLOR) {
                  // À¯´ÏÅ© ¾ÆÀÌÅÛÀÌ¸é
                  //									if(colorSet2
                  //== QUEST_ITEM_COLOR)
                  // colorSet2 = MItem::GetQuestItemColorset();
                  // else
                  // colorSet2 = MItem::GetUniqueItemColorset();

                  colorSet2 = MItem::GetSpecialColorItemColorset(colorSet2);
                  if (addonInfo.ItemClass != ITEM_CLASS_COAT &&
                      addonInfo.ItemClass != ITEM_CLASS_TROUSER)
                    colorSet1 = colorSet2;
                }

                CIndexSprite::SetUsingColorSet(colorSet1, colorSet2);

                // ¾îµÓ°Ô Âï±â
                if (pCreature->IsFade()) {
                  m_pSurface->BltIndexSpriteDarkness(&pointTemp, pSprite, 1);
                } else {
                  m_pSurface->BltIndexSprite(&pointTemp, pSprite);
                }
              }

              // Á¤»óÀûÀÎ Ãâ·Â
              // CIndexSprite::SetUsingColorSet( addonInfo.ColorSet1,
              // addonInfo.ColorSet2 ); m_pSurface->BltIndexSprite(&pointTemp,
              // pSprite);
            }
          }
        }

        m_pSurface->Unlock();
      }
    } break;

    case 2000: {
      if ((GetTickCount() - OustersFinEvent->eventStartTickCount) / 4000 > 0) {
        OustersFinEvent->parameter2++;

        if (OustersFinEvent->parameter2 > 8) {
          g_pPlayer->ClearChatString();

          if (OustersFinEvent->parameter2 == 9) {
            g_pPlayer->SetDead();
            PlaySoundForce(g_pPlayer->IsFemale() ? SOUND_VAMPIRE_DIE_FEMALE
                                                 : SOUND_VAMPIRE_DIE_MALE);
            fadeSpeed = 32 * 4;
            fadeColor[0] = 255;
            fadeColor[1] = 0;
            fadeColor[2] = 0;
          }

          if (OustersFinEvent->parameter2 > 9) {
            fadeColor[0] = 0;
            fadeColor[1] = 0;
            fadeColor[2] = 0;
            fadeDirect = 31;

            if (OustersFinEvent->parameter2 > 10) {
              OustersFinEvent->eventStartTickCount = GetTickCount();
              OustersFinEvent->parameter1 = 9998;
              OustersFinEvent->parameter4 = EVENTBACKGROUNDID_OUSTERS_VAMPIRE;
              g_pMP3->Play(false);
              fadeDirect = 0;
            }
          }
        } else {
          PlaySoundForce(soundID);
          g_pPlayer->SetChatString(
              (*g_pGameStringTable)[STRING_MESSAGE_AMATA_SCRIPT_1 +
                                    OustersFinEvent->parameter2]
                  .GetString());
        }

        if (OustersFinEvent->parameter2 < 11)
          OustersFinEvent->eventStartTickCount = GetTickCount();
      }

      if (m_pSurface->Lock()) {
        const int char_plus_x = 10, char_plus_y = 24;

        POINT p[8] = {
            {400 - m_OustersFinSPK[2].GetWidth() / 2 + char_plus_x,
             160 - m_OustersFinSPK[2].GetHeight() + char_plus_y},
            {300 - m_OustersFinSPK[4].GetWidth() / 2 + char_plus_x,
             210 - m_OustersFinSPK[4].GetHeight() + char_plus_y},
            {240 - m_OustersFinSPK[5].GetWidth() / 2 + char_plus_x,
             300 - m_OustersFinSPK[5].GetHeight() + char_plus_y},
            {300 - m_OustersFinSPK[6].GetWidth() / 2 + char_plus_x,
             390 - m_OustersFinSPK[6].GetHeight() + char_plus_y},
            {400 - m_OustersFinSPK[7].GetWidth() / 2 + char_plus_x,
             440 - m_OustersFinSPK[7].GetHeight() + char_plus_y},
            {500 - m_OustersFinSPK[8].GetWidth() / 2 + char_plus_x,
             390 - m_OustersFinSPK[8].GetHeight() + char_plus_y},
            {560 - m_OustersFinSPK[9].GetWidth() / 2 + char_plus_x,
             300 - m_OustersFinSPK[9].GetHeight() + char_plus_y},
            {500 - m_OustersFinSPK[10].GetWidth() / 2 + char_plus_x,
             210 - m_OustersFinSPK[10].GetHeight() + char_plus_y},
        };

        m_pSurface->BltSprite(&p[0], &m_OustersFinSPK[2]);
        POINT strPoint = p[0];
        strPoint.x -= 15;
        strPoint.y -= 15;
        DrawChatString(&strPoint, g_pPlayer, RGB(255, 255, 255));

        if (OustersFinEvent->parameter2 > 0) {
          for (int i = 0; i < 7; i++) {
            m_pSurface->BltSprite(&p[i + 1], &m_OustersFinSPK[4 + i]);
          }
        }

        int body, action, direction, frame, creature_type;

        MCreature *pCreature = g_pPlayer;

        body = pCreature->GetCreatureFrameID(0);
        action = pCreature->GetAction();
        direction = 6; // pCreature->GetDirection();
        frame =
            pCreature
                ->GetFrame(); //%m_CreatureFPK[body][action][direction].GetCount();
        creature_type = pCreature->GetCreatureType();

        // vampire
        FRAME_ARRAY &FA = m_CreatureFPK[body][action][direction];

        if (FA.GetSize() > frame) {
          CFrame &Frame = FA[frame];
          int sprite =
                  Frame
                      .GetSpriteID(), // m_CreatureFPK[body][action][direction][frame].GetSpriteID(),
              cx =
                  Frame
                      .GetCX(), // m_CreatureFPK[body][action][direction][frame].GetCX(),
              cy =
                  Frame
                      .GetCY(); // m_CreatureFPK[body][action][direction][frame].GetCY();

          CIndexSprite *pSprite = &GetCreatureSprite(sprite, body);

          //							if
          //(pSprite->IsNotInit())
          //							{
          //								LoadFromFileCreatureActionSPK(
          // body, action );
          //							}

          int colorSet1 = pCreature->GetBodyColor1();
          int colorSet2 = pCreature->GetBodyColor2();
          if (colorSet1 == QUEST_ITEM_COLOR || colorSet1 == UNIQUE_ITEM_COLOR)
            colorSet1 = MItem::GetSpecialColorItemColorset(colorSet1);

          if (colorSet2 == QUEST_ITEM_COLOR || colorSet2 == UNIQUE_ITEM_COLOR)
            colorSet2 = MItem::GetSpecialColorItemColorset(colorSet2);

          POINT pointTemp;

          // ÁÂÇ¥ º¸Á¤
          pointTemp.x = 384 + cx;
          pointTemp.y = 312 + cy;

          CIndexSprite::SetUsingColorSet(colorSet1, colorSet2);
          m_pSurface->BltIndexSprite(&pointTemp, pSprite);
        }

        m_pSurface->Unlock();
      }
    } break;

    case 9998:
      if (m_pSurface->Lock()) {
        int scroll_progress =
            -500 + (GetTickCount() - OustersFinEvent->eventStartTickCount) / 66;

        const int spriteID = 0;
        const int scroll_x =
            SURFACE_WIDTH / 2 - m_AdvacementQuestEnding[0].GetWidth() / 2;
        const int scroll_y = (SURFACE_HEIGHT - 500) / 2;
        /*
        #ifdef CONVERT_1024_768
        #else
                                        const int scroll_x =
        800/2-m_OustersFinSPK[spriteID].GetWidth()/2, scroll_y = 50; #endif
        */

        int scroll = ((scroll_progress < 0) ? 0 : scroll_progress);
        int scroll2 =
            ((scroll_progress < 0) ? scroll_progress : scroll_progress);
        int scroll3 = ((scroll_progress < 0) ? 500 + scroll_progress : 500);

        Rect rect(0, scroll, m_OustersFinSPK[spriteID].GetWidth(),
                  min(scroll3, m_OustersFinSPK[spriteID].GetHeight() - scroll));
        S_SURFACEINFO surface_info;
        SetSurfaceInfo(&surface_info, gpC_base->m_p_DDSurface_back->GetDDSD());

        int x = scroll_x, y = scroll_y - scroll2;
        RECT rt;
        rt.left = max(-x, rect.x);
        rt.top = max(-y, rect.y);
        rt.right = min(rect.x + rect.w, SURFACE_WIDTH - x);
        rt.bottom = min(rect.y + rect.h, SURFACE_HEIGHT - y);

        if (rt.bottom < rt.top) {
          OustersFinEvent->parameter1 = 9999;
        }

        if (rt.left < rt.right && rt.top < rt.bottom) {
          WORD *p_dest = (WORD *)surface_info.p_surface + x + rt.left;
          p_dest = (WORD *)((BYTE *)p_dest + (y + rt.top) * surface_info.pitch);

          // void BltClip(WORD *pDest, WORD pitch, RECT* pRect); // in CSprite.h
          m_OustersFinSPK[spriteID].BltClipWidth(p_dest, surface_info.pitch,
                                                 &rt);
        }

        Rect rect2(
            0, 0, m_OustersFinSPK[1].GetWidth(),
            min(scroll3 - (m_OustersFinSPK[spriteID].GetHeight() - scroll) - 50,
                m_OustersFinSPK[1].GetHeight()));

        x = scroll_x + m_OustersFinSPK[spriteID].GetWidth() / 2 -
            m_OustersFinSPK[1].GetWidth() / 2;
        y = scroll_y +
            max(200, (m_OustersFinSPK[spriteID].GetHeight() - scroll + 50));
        rt.left = max(-x, rect2.x);
        rt.top = max(-y, rect2.y);
        rt.right = min(rect2.x + rect2.w, SURFACE_WIDTH - x);
        rt.bottom = min(rect2.y + rect2.h, SURFACE_HEIGHT - y);
        if (rt.left < rt.right && rt.top < rt.bottom) {
          WORD *p_dest = (WORD *)surface_info.p_surface + x + rt.left;
          p_dest = (WORD *)((BYTE *)p_dest + (y + rt.top) * surface_info.pitch);

          // void BltClip(WORD *pDest, WORD pitch, rect2* prect2); // in
          // CSprite.h
          m_OustersFinSPK[1].BltClipWidth(p_dest, surface_info.pitch, &rt);
        }

        m_pSurface->Unlock();
      }
      break;

    case 9999:
      bFinEnd = true;
      break;
    }

    RECT rect;
    rect.left = 0;
    rect.right = CLIPSURFACE_WIDTH;
    rect.top = 0;
    rect.bottom = CLIPSURFACE_HEIGHT;

    DrawAlphaBox(
        &rect, fadeColor[0], fadeColor[1], fadeColor[2],
        min(31, (GetTickCount() - OustersFinEvent->eventStartTickCount) /
                    fadeSpeed) ^
            fadeDirect);

    if (bFinEnd) {
      //				char szTemp[512];
      //				sprintf(szTemp, "%d",
      //(GetTickCount()-OustersFinEvent->eventStartTickCount)/1000);
      //				UI_AddChatToHistory( szTemp, szTemp, 0,
      // RGB(255, 255, 255) );
      UI_REQUEST_DIE_TIMER_RESET();
      g_pEventManager->RemoveEvent(EVENTID_OUSTERS_FIN);
      m_OustersFinSPK.Release();
    }
  }
  return bDrawBackGround;
}

POINT MTopView::CalculateChatStringPoint(POINT *pPoint, MCreature *pCreature,
                                         bool SubFontHeight) {
  POINT pointTemp;

  //----------------------------------------
  // ÀÌ¸§ Ãâ·ÂÇÒ ÁÂÇ¥ ÁöÁ¤
  //----------------------------------------
  const int FontHeight = g_pClientConfig->FONT_HEIGHT;
  const int FontHeight2 = FontHeight << 1;

  pointTemp = *pPoint;
  if (pointTemp.x < 0)
    pointTemp.x = 0;
  if (pointTemp.x >= RESOLUTION_X)
    pointTemp.x = RESOLUTION_X - 1;

  //----------------------------------------
  // Level Name ÂïÀ» À§Ä¡µµ °è»ê
  //----------------------------------------
  if (pCreature->HasLevelName()) {
    if (SubFontHeight)
      pointTemp.y = pPoint->y - FontHeight2;

    if (pointTemp.y < FontHeight2)
      pointTemp.y = FontHeight2;
  }
  //----------------------------------------
  // ±×³É ÀÌ¸§¸¸ ÂïÀ» ¶§
  //----------------------------------------
  else {
    if (SubFontHeight)
      pointTemp.y = pPoint->y - FontHeight;

    if (pointTemp.y < FontHeight)
      pointTemp.y = FontHeight;
  }

  if (pointTemp.y >= RESOLUTION_Y)
    pointTemp.y = RESOLUTION_Y - 1;

  return pointTemp;
}

void MTopView::AddDrawNameCreature(POINT *pPoint, MCreature *pCreature,
                                   bool SubFontHeight) {
  if (pCreature == NULL || pPoint == NULL || pCreature->GetName() == NULL)
    return;

  DrawNameCreatureInfo dncInfo;

  dncInfo.ptDrawPostion =
      CalculateChatStringPoint(pPoint, pCreature, SubFontHeight);
  dncInfo.pCreature = pCreature;
  dncInfo.bOverText = false;

  m_DrawNameCreatureInfoVec.push_back(dncInfo);
}

void MTopView::ClearDrawNameCreature() { m_DrawNameCreatureInfoVec.clear(); }

bool MTopView::IsDrawNameCreature(MCreature *pCreature) {
  DRAWNAMECREATUREINFO_VEC::iterator pos = m_DrawNameCreatureInfoVec.begin();
  DRAWNAMECREATUREINFO_VEC::iterator endpos = m_DrawNameCreatureInfoVec.end();

  for (; pos != endpos; ++pos)
    if (pos->pCreature == pCreature)
      return true;

  return false;
}

