void MTopView::VampireMoveIntoPortal(MCreature *pCreature) {
  // Vampire ¾Æ´Ñ ³ðÀÌ ¿©±â µé¾î¿À¸é ¾ÈµÊ
  if (pCreature == NULL || !pCreature->IsVampire())
    return;

  int x = pCreature->GetX();
  int y = pCreature->GetY();
  MFakeCreature *pFakeCreature = g_pZone->NewFakeCreature(pCreature, x, y);

  pFakeCreature->SetFakeCreatureType(MFakeCreature::FAKE_CREATURE_TO_PORTAL);

  //------------------------------------------------------
  // Fake Creature¸¦ Zone¿¡ Ãß°¡
  //------------------------------------------------------
  if (!g_pZone->AddFakeCreature(pFakeCreature)) {
    delete pFakeCreature;
  }

  //------------------------------------------------------
  // ºùºù µ¹¾Æ¼­ Ä³¸¯À» ÈÖ°¨´Â ÀÌÆåÆ® Ç¥Çö..
  //------------------------------------------------------
  ExecuteActionInfoFromMainNode(
      RESULT_MAGIC_BLOODY_TUNNEL_INTO, // »ç¿ë ±â¼ú ¹øÈ£

      x, y, 0,
      DIRECTION_DOWN, // »ç¿ë ¹æÇâ

      pFakeCreature->GetID(), // ¸ñÇ¥¿¡ ´ëÇÑ Á¤º¸
      x, y, 0,

      0, // ±â¼úÀÇ (³²Àº) Áö¼Ó ½Ã°£

      NULL,

      false);
}
CIndexSprite &MTopView::GetCreatureSprite(int spriteIdx, int body) {
  // int a = (*g_pCreatureSpriteTable)[body].FrameID;
  if (body == 473)
  {
    Phoenix_CreatureDrawAudit_Log(
        "GetCreatureSprite body=%d sprite=%d slot=%d spk7Size=%d prepared=%d",
        body, spriteIdx, Phoenix_GetCreatureSpritePackSlot(body),
        (int)m_CreatureSPK7.GetSize(),
        (int)m_CreatureSPK7.IsElementPrepared((WORD)spriteIdx));
  }
  switch (Phoenix_GetCreatureSpritePackSlot(body))
  {
  case 1:
    return m_CreatureSPK[spriteIdx];
  case 2:
    return m_CreatureSPK2[spriteIdx];
  case 7:
    return m_CreatureSPK7[spriteIdx];
  default:
    return m_CreatureSPK3[spriteIdx];
  }
}

CShadowSprite &MTopView::GetCreatureShadowSprite(int spriteIdx, int body) {
  // int a = (*g_pCreatureSpriteTable)[body].FrameID;
  if (body < 287)
    return m_CreatureSSPK[spriteIdx];
  // #if __CONTENTS(__ONIBLA)
  else if (body > 286 && body < 409) {
    return m_CreatureSSPK2[spriteIdx];
  } else {
    return m_CreatureSSPK3[spriteIdx];
  }
  // #endif //__ONIBLA
}
